#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
==============================================================================
  THE BLADE OF DAMNATION
  A 2D blade-duel fighting game  (Python 3.10+, pygame 2.x, numpy)
------------------------------------------------------------------------------
  Setting : A fictional, highly-mystical modern world.  The ruins of a
            romanesque cathedral rot in the middle of a cursed swamp,
            infested by a demonic presence.
  Fighters: CECILIA - crimson/black gothic-lolita Asura swordswoman (katana)
            KIRI    - kitsune-masked twin-blade martial artist
  Style   : Samurai Shodown / Soulcalibur inspired blade combat with
            deflects, blade clashes, guard meters, stance play and unique
            per-character systems (Curse Brand / Kitsune Tempo).
  Rating  : R18 - blood and gore are depicted (can be toggled in Options).

  Everything (graphics, sprites, music, sound effects) is generated by code
  at start-up: no external asset files are required.

  Requirements :  pip install pygame numpy
  Run          :  python blade_of_damnation.py

  CONTROLS (default)
    Player 1 : W A S D  move/jump/crouch  | J Light  K Heavy  U Kick
               I Skill  L Deflect         | (Light+Heavy = Throw)
    Player 2 : Arrows                     | Numpad 1 Light 2 Heavy 3 Kick
               5 Skill  6 Deflect  (or  , . / ; '  on laptops)
    Gamepads : D-pad/left stick, A Light, X Heavy, B Kick, Y Skill, RB Deflect
    System   : Enter/Space confirm, Esc back/pause, F1 hitboxes, F11 fullscreen
  Sprite design : every pose in the game is an individually authored
  keyframe (joint targets, head turn, torso twist, hair, skirt, blade angle,
  smear arcs...) rendered to a supersampled, shaded vector sprite and cached.
==============================================================================
"""
import math
import random
import sys
import os
import time
import threading

import pygame
import numpy as np

# ----------------------------------------------------------------------------
#  GLOBAL CONSTANTS
# ----------------------------------------------------------------------------
W, H = 960, 540              # logical resolution
FPS = 60
GROUND_Y = 478               # screen y of the floor line
STAGE_W = 2000               # world width in logical pixels
CS = 1.5                     # sprite unit -> logical pixel
SS = 2                       # supersampling factor for sprite rendering
K_RENDER = CS * SS           # unit -> supersampled pixel
TAU = math.tau

# Canvas used for rendering one sprite frame, in sprite units
CANVAS_W, CANVAS_H = 400, 320
CANVAS_OX, CANVAS_OY = 200, 250      # ground-centre origin inside canvas

CFG = {
    'music_vol': 0.55, 'sfx_vol': 0.8, 'gore': True, 'shake': True,
    'difficulty': 3, 'round_time': 60, 'rounds': 2, 'show_boxes': False,
    'show_fps': False, 'fullscreen': False, 'ai_p2': True,
}


# ----------------------------------------------------------------------------
#  MATH / COLOUR HELPERS
# ----------------------------------------------------------------------------
def clamp(v, a, b):
    return a if v < a else (b if v > b else v)


def lerp(a, b, t):
    return a + (b - a) * t


def sgn(v):
    return (v > 0) - (v < 0)


def mix(c1, c2, t):
    return (int(c1[0] + (c2[0] - c1[0]) * t),
            int(c1[1] + (c2[1] - c1[1]) * t),
            int(c1[2] + (c2[2] - c1[2]) * t))


def shade(c, f):
    return (clamp(int(c[0] * f), 0, 255), clamp(int(c[1] * f), 0, 255), clamp(int(c[2] * f), 0, 255))


def tint(c, r, g=None, b=None):
    if g is None:
        g = b = r
    return (clamp(int(c[0] + r), 0, 255), clamp(int(c[1] + g), 0, 255), clamp(int(c[2] + b), 0, 255))


def vadd(a, b):
    return (a[0] + b[0], a[1] + b[1])


def vsub(a, b):
    return (a[0] - b[0], a[1] - b[1])


def vmul(a, k):
    return (a[0] * k, a[1] * k)


def vlen(a):
    return math.hypot(a[0], a[1])


def vnorm(a):
    d = math.hypot(a[0], a[1])
    if d < 1e-6:
        return (0.0, 0.0)
    return (a[0] / d, a[1] / d)


def vrot(p, deg):
    r = math.radians(deg)
    c, s = math.cos(r), math.sin(r)
    return (p[0] * c - p[1] * s, p[0] * s + p[1] * c)


def vlerp(a, b, t):
    return (a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t)


def vdir(deg, length=1.0):
    r = math.radians(deg)
    return (math.cos(r) * length, math.sin(r) * length)


def vang(a, b):
    return math.degrees(math.atan2(b[1] - a[1], b[0] - a[0]))


def ik2(root, target, l1, l2, s):
    """Two-bone IK. Returns (mid joint, end point).  s = +1/-1 bend side."""
    dx, dy = target[0] - root[0], target[1] - root[1]
    d = math.hypot(dx, dy)
    if d < 1e-4:
        dx, dy, d = 0.0, 1.0, 1.0
    maxd = l1 + l2 - 0.02
    mind = abs(l1 - l2) + 0.5
    ux, uy = dx / d, dy / d
    d = clamp(d, mind, maxd)
    a = (l1 * l1 - l2 * l2 + d * d) / (2 * d)
    h = math.sqrt(max(l1 * l1 - a * a, 0.0))
    mx, my = root[0] + ux * a, root[1] + uy * a
    mid = (mx - uy * h * s, my + ux * h * s)
    end = (root[0] + ux * d, root[1] + uy * d)
    return mid, end


def catmull(pts, n=5):
    """Catmull-Rom spline through pts, n samples per segment."""
    if len(pts) < 3:
        return list(pts)
    out = []
    P = [pts[0]] + list(pts) + [pts[-1]]
    for i in range(1, len(P) - 2):
        p0, p1, p2, p3 = P[i - 1], P[i], P[i + 1], P[i + 2]
        for j in range(n):
            t = j / n
            t2, t3 = t * t, t * t * t
            x = 0.5 * ((2 * p1[0]) + (-p0[0] + p2[0]) * t + (2 * p0[0] - 5 * p1[0] + 4 * p2[0] - p3[0]) * t2
                       + (-p0[0] + 3 * p1[0] - 3 * p2[0] + p3[0]) * t3)
            y = 0.5 * ((2 * p1[1]) + (-p0[1] + p2[1]) * t + (2 * p0[1] - 5 * p1[1] + 4 * p2[1] - p3[1]) * t2
                       + (-p0[1] + 3 * p1[1] - 3 * p2[1] + p3[1]) * t3)
            out.append((x, y))
    out.append(pts[-1])
    return out


def ease_out(t):
    return 1 - (1 - t) * (1 - t)


def ease_in(t):
    return t * t


def ease_io(t):
    return t * t * (3 - 2 * t)


def rect_overlap(a, b):
    return a[0] < b[0] + b[2] and b[0] < a[0] + a[2] and a[1] < b[1] + b[3] and b[1] < a[1] + a[3]


# ----------------------------------------------------------------------------
#  FONTS & TEXT
# ----------------------------------------------------------------------------
_font_cache = {}
_text_cache = {}
SERIF_NAMES = 'palatinolinotype,bookantiqua,georgia,garamond,timesnewroman,dejavuserif,liberationserif,freeserif'
SANS_NAMES = 'bahnschrift,trebuchetms,verdana,dejavusans,liberationsans,freesans,arial'


def get_font(size, bold=True, italic=False, serif=True):
    key = (size, bold, italic, serif)
    f = _font_cache.get(key)
    if f is None:
        try:
            f = pygame.font.SysFont(SERIF_NAMES if serif else SANS_NAMES, size, bold, italic)
        except Exception:
            f = pygame.font.Font(None, int(size * 1.2))
        _font_cache[key] = f
    return f


def text_surf(text, size, color=(255, 255, 255), outline=None, bold=True, italic=False, serif=True,
              shadow=None, grad=None):
    """Cached rendered text with optional outline, drop shadow and vertical gradient."""
    key = (text, size, color, outline, bold, italic, serif, shadow, grad)
    s = _text_cache.get(key)
    if s is not None:
        return s
    if len(_text_cache) > 600:
        _text_cache.clear()
    font = get_font(size, bold, italic, serif)
    base = font.render(text, True, color)
    if grad is not None:
        g = pygame.Surface(base.get_size(), pygame.SRCALPHA)
        for yy in range(base.get_height()):
            t = yy / max(1, base.get_height() - 1)
            col = mix(grad[0], grad[1], t) if len(grad) == 2 else (mix(grad[0], grad[1], t * 2) if t < 0.5 else mix(grad[1], grad[2], (t - 0.5) * 2))
            pygame.draw.line(g, col, (0, yy), (base.get_width(), yy))
        base = base.copy()
        base.blit(g, (0, 0), special_flags=pygame.BLEND_RGBA_MULT)
        # restore the glyph alpha (mult above keeps alpha of both)
    pad = 2
    ow = 0
    if outline:
        ow = max(1, size // 14) + 1
    sh = 0
    if shadow:
        sh = max(2, size // 12)
    w, h = base.get_width() + (ow + pad) * 2 + sh, base.get_height() + (ow + pad) * 2 + sh
    surf = pygame.Surface((w, h), pygame.SRCALPHA)
    ox = oy = ow + pad
    if shadow:
        sd = font.render(text, True, shadow)
        surf.blit(sd, (ox + sh, oy + sh))
    if outline:
        ol = font.render(text, True, outline)
        for dx in range(-ow, ow + 1):
            for dy in range(-ow, ow + 1):
                if dx * dx + dy * dy <= ow * ow + 1:
                    surf.blit(ol, (ox + dx, oy + dy))
    surf.blit(base, (ox, oy))
    _text_cache[key] = surf
    return surf


def draw_text(dst, text, size, pos, color=(255, 255, 255), anchor='topleft', outline=(10, 4, 12),
              shadow=None, italic=False, serif=True, alpha=255, grad=None, bold=True):
    s = text_surf(text, size, color, outline, bold, italic, serif, shadow, grad)
    r = s.get_rect()
    setattr(r, anchor, pos)
    if alpha < 255:
        s = s.copy()
        s.set_alpha(alpha)
    dst.blit(s, r)
    return r


# ----------------------------------------------------------------------------
#  GLOW / GRADIENT TEXTURES (numpy built, cached)
# ----------------------------------------------------------------------------
_glow_cache = {}


def glow_tex(r, col, power=2.0):
    """RGB surface for additive blending: radial falloff of colour."""
    key = (int(r), col, power)
    s = _glow_cache.get(key)
    if s is None:
        r = max(2, int(r))
        yy, xx = np.mgrid[-r:r, -r:r]
        d = np.sqrt((xx + 0.5) ** 2 + (yy + 0.5) ** 2) / r
        a = np.clip(1 - d, 0, 1) ** power
        arr = np.zeros((2 * r, 2 * r, 3), np.uint8)
        for i in range(3):
            arr[:, :, i] = (a * col[i]).astype(np.uint8)
        s = pygame.Surface((2 * r, 2 * r))
        pygame.surfarray.blit_array(s, arr.swapaxes(0, 1))
        _glow_cache[key] = s
    return s


def draw_glow(dst, pos, r, col, power=2.0, intensity=1.0):
    if intensity <= 0:
        return
    if intensity < 1.0:
        col = shade(col, intensity)
    t = glow_tex(r, col, power)
    dst.blit(t, (pos[0] - t.get_width() // 2, pos[1] - t.get_height() // 2), special_flags=pygame.BLEND_RGB_ADD)


def vgrad_surface(w, h, stops):
    """Vertical gradient surface. stops = [(t, (r,g,b)), ...]."""
    s = pygame.Surface((w, h))
    for y in range(h):
        t = y / max(1, h - 1)
        for i in range(len(stops) - 1):
            if stops[i][0] <= t <= stops[i + 1][0]:
                u = (t - stops[i][0]) / max(1e-6, stops[i + 1][0] - stops[i][0])
                pygame.draw.line(s, mix(stops[i][1], stops[i + 1][1], u), (0, y), (w, y))
                break
    return s


def radial_alpha(r, col, power=1.5, max_alpha=255):
    """SRCALPHA radial blob (normal blending)."""
    yy, xx = np.mgrid[-r:r, -r:r]
    d = np.sqrt((xx + 0.5) ** 2 + (yy + 0.5) ** 2) / r
    a = (np.clip(1 - d, 0, 1) ** power * max_alpha).astype(np.uint8)
    s = pygame.Surface((2 * r, 2 * r), pygame.SRCALPHA)
    s.fill((col[0], col[1], col[2], 0))
    pygame.surfarray.pixels_alpha(s)[:, :] = a.swapaxes(0, 1)
    return s


def tint_surface(src, col, amount=1.0):
    """Return copy with RGB pushed toward col additive (white flash)."""
    s = src.copy()
    s.fill((int(col[0] * amount), int(col[1] * amount), int(col[2] * amount), 0), special_flags=pygame.BLEND_RGB_ADD)
    return s


def silhouette(src, col):
    s = src.copy()
    s.fill((0, 0, 0, 255), special_flags=pygame.BLEND_RGBA_MULT)
    s.fill((col[0], col[1], col[2], 0), special_flags=pygame.BLEND_RGBA_ADD)
    return s


class Timer:
    """Tiny helper for FPS smoothing."""
    def __init__(self):
        self.t = time.perf_counter()
        self.fps = 60.0

    def tick(self):
        n = time.perf_counter()
        dt = n - self.t
        self.t = n
        if dt > 0:
            self.fps = lerp(self.fps, 1.0 / dt, 0.1)
        return dt

# ============================================================================
#  AUDIO ENGINE  -  every sound effect, voice and music loop is synthesised
#  with numpy at start-up (no external files).
# ============================================================================
SR = 22050
_RNG = np.random.default_rng(1666)


def _t(dur):
    return np.arange(int(dur * SR), dtype=np.float32) / SR


def noise(dur):
    return _RNG.uniform(-1, 1, int(dur * SR)).astype(np.float32)


def mtof(m):
    return 440.0 * 2.0 ** ((m - 69) / 12.0)


def sweep(f0, f1, dur, k=20.0):
    t = _t(dur)
    f = f1 + (f0 - f1) * np.exp(-t * k)
    return np.sin(TAU * np.cumsum(f) / SR).astype(np.float32)


def sine(f, dur):
    return np.sin(TAU * f * _t(dur)).astype(np.float32)


def saw(f, dur, vib=0.0):
    t = _t(dur)
    if vib:
        ph = np.cumsum(f * (1 + vib * np.sin(TAU * 5.2 * t))) / SR
    else:
        ph = t * f
    return (2 * (ph % 1.0) - 1).astype(np.float32)


def square(f, dur, pw=0.5):
    t = _t(dur)
    return np.where((t * f) % 1.0 < pw, 1.0, -1.0).astype(np.float32)


def env(dur, a=0.001, d=8.0):
    t = _t(dur)
    return (np.minimum(t / max(a, 1e-4), 1.0) * np.exp(-t * d)).astype(np.float32)


def fft_filter(x, lo=None, hi=None, order=4):
    n = len(x)
    if n < 8:
        return x
    X = np.fft.rfft(x)
    fr = np.fft.rfftfreq(n, 1.0 / SR)
    m = np.ones_like(fr)
    if hi:
        m = m / (1 + (fr / hi) ** order)
    if lo:
        m = m * (1 - 1 / (1 + (fr / lo) ** order))
    return np.fft.irfft(X * m, n).astype(np.float32)


def band(x, f, bw):
    n = len(x)
    X = np.fft.rfft(x)
    fr = np.fft.rfftfreq(n, 1.0 / SR)
    m = np.exp(-0.5 * ((fr - f) / bw) ** 2)
    return np.fft.irfft(X * m, n).astype(np.float32)


def drive(x, g):
    return np.tanh(x * g).astype(np.float32)


def echo(x, delay, fb, taps=4, tail=0.0):
    ds = int(delay * SR)
    out = np.zeros(len(x) + ds * taps + int(tail * SR), np.float32)
    out[:len(x)] += x
    for i in range(1, taps + 1):
        out[ds * i: ds * i + len(x)] += x * (fb ** i)
    return out


def fit(x, n):
    if len(x) >= n:
        return x[:n]
    return np.pad(x, (0, n - len(x)))


def norm(x, peak=0.9):
    m = float(np.max(np.abs(x))) if len(x) else 0
    return x * (peak / m) if m > 1e-6 else x


def fade_tail(x, ms=8):
    n = min(len(x), int(ms * SR / 1000))
    if n > 1:
        x = x.copy()
        x[-n:] *= np.linspace(1, 0, n)
    return x


def stereo(x, pan=0.0):
    l = math.cos((pan + 1) * math.pi / 4)
    r = math.sin((pan + 1) * math.pi / 4)
    return np.stack([x * l, x * r], axis=1)


def to_sound(x, gain=1.0):
    if x.ndim == 1:
        x = stereo(x)
    x = np.clip(x * gain, -1, 1)
    a = np.ascontiguousarray((x * 32000).astype(np.int16))
    return pygame.sndarray.make_sound(a)


def mixin(buf, snd, start, gain=1.0, pan=0.0, wrap=True):
    n = len(buf)
    if start >= n:
        return
    l = math.cos((pan + 1) * math.pi / 4) * gain
    r = math.sin((pan + 1) * math.pi / 4) * gain
    m = min(len(snd), n - start)
    buf[start:start + m, 0] += snd[:m] * l
    buf[start:start + m, 1] += snd[:m] * r
    if wrap and len(snd) > m:
        rest = min(len(snd) - m, n)
        buf[:rest, 0] += snd[m:m + rest] * l
        buf[:rest, 1] += snd[m:m + rest] * r


# ----------------------------------------------------------------------------
#  Instruments
# ----------------------------------------------------------------------------
def s_kick(punch=1.0, dur=0.30, low=44.0):
    t = _t(dur)
    f = low + 170 * np.exp(-t * 42)
    body = np.sin(TAU * np.cumsum(f) / SR) * np.exp(-t * 7.0)
    click = np.zeros_like(t)
    c = noise(0.008)
    click[:len(c)] = c * np.linspace(1, 0, len(c))
    y = drive(body + click * 0.35, 2.2 * punch)
    return fade_tail(y)


def s_snare(dur=0.24, tone=190, snap=1.0):
    t = _t(dur)
    tn = np.sin(TAU * tone * t + 3 * np.exp(-t * 30)) * np.exp(-t * 24)
    nz = fft_filter(noise(dur), lo=1800) * np.exp(-t * 15)
    return fade_tail(drive(tn * 0.7 + nz * 0.95 * snap, 1.6))


def s_hat(open_=False, dur=None):
    dur = dur or (0.22 if open_ else 0.05)
    t = _t(dur)
    nz = fft_filter(noise(dur), lo=7500) * np.exp(-t * (14 if open_ else 70))
    return fade_tail(nz * 0.55)


def s_clap():
    out = np.zeros(int(0.25 * SR), np.float32)
    for i, d in enumerate((0.0, 0.011, 0.022)):
        n = band(noise(0.18), 1500, 700) * env(0.18, 0.001, 30 if i < 2 else 14)
        s = int(d * SR)
        out[s:s + len(n)] += n[:len(out) - s]
    return fade_tail(drive(out * 2.2, 1.5))


def s_crash(dur=1.6):
    t = _t(dur)
    return fade_tail(fft_filter(noise(dur), lo=4500) * np.exp(-t * 3.0) * 0.6, 20)


def s_tom(f=110, dur=0.3):
    t = _t(dur)
    return fade_tail(np.sin(TAU * np.cumsum(f + 60 * np.exp(-t * 20)) / SR) * np.exp(-t * 9))


def s_bass(m, dur, accent=False, cutoff=620, dist=3.5):
    f = mtof(m)
    x = saw(f, dur) * 0.7 + square(f * 0.5, dur) * 0.6 + sine(f * 0.5, dur) * 0.3
    x = drive(fft_filter(x, hi=cutoff * (1.7 if accent else 1.0)), dist)
    return fade_tail(x * env(dur, 0.002, 2.0 if accent else 5.0))


def s_stab(m, dur, bright=3200, det=0.006, vib=0.0):
    f = mtof(m)
    x = saw(f, dur, vib) + saw(f * (1 + det), dur, vib) + saw(f * (1 - det), dur, vib) * 0.8
    x = fft_filter(x, hi=bright)
    return fade_tail(x * env(dur, 0.003, 6.0 if dur < 0.4 else 2.0) * 0.33)


def s_bell(m, dur=0.9, idx=2.8, ratio=3.5):
    f = mtof(m)
    t = _t(dur)
    mod = np.sin(TAU * f * ratio * t) * idx * np.exp(-t * 6)
    y = np.sin(TAU * f * t + mod) * np.exp(-t * 4.0)
    y += 0.3 * np.sin(TAU * f * 2.0 * t) * np.exp(-t * 7)
    return fade_tail(y.astype(np.float32) * 0.5)


VOWELS = {
    'a': ((800, 110, 1.0), (1150, 130, 0.6), (2900, 200, 0.25), (3500, 250, 0.1)),
    'o': ((450, 80, 1.0), (800, 100, 0.55), (2830, 200, 0.15)),
    'e': ((400, 80, 1.0), (2000, 150, 0.45), (2800, 200, 0.25)),
    'i': ((300, 70, 1.0), (2300, 150, 0.35), (3000, 200, 0.2)),
    'u': ((325, 70, 1.0), (700, 90, 0.4), (2530, 200, 0.1)),
}


def voice(f0, dur, vowel='a', f_end=None, rasp=0.2, vib=0.0, breath=0.05, vowel2=None, a=0.01, d=3.0, shape=1.0):
    """Formant voice: glottal saw -> spectral formant envelope."""
    t = _t(dur)
    n = len(t)
    f = np.linspace(f0, f_end if f_end else f0, n) * (1 + vib * np.sin(TAU * 5.5 * t))
    ph = np.cumsum(f) / SR
    g = 2 * (ph % 1.0) - 1
    g = g * (1 - rasp * 0.5) + rasp * noise(dur) * 0.6
    g += 0.4 * np.sin(TAU * ph * 0.5)
    X = np.fft.rfft(g)
    fr = np.fft.rfftfreq(n, 1.0 / SR)

    def shape_for(vw):
        m = np.full_like(fr, 0.02)
        for fc, bw, amp in VOWELS[vw]:
            m += amp * np.exp(-0.5 * ((fr - fc) / bw) ** 2)
        return m
    m = shape_for(vowel)
    if vowel2:
        y1 = np.fft.irfft(X * m, n)
        y2 = np.fft.irfft(X * shape_for(vowel2), n)
        w = np.linspace(0, 1, n)
        y = y1 * (1 - w) + y2 * w
    else:
        y = np.fft.irfft(X * m, n)
    y = y.astype(np.float32)
    y += breath * fft_filter(noise(dur), lo=2000) * 0.3
    e = np.minimum(t / a, 1.0) * np.exp(-t * d / max(dur, 0.05) * shape)
    return fade_tail(norm(drive(y * 1.4, 1.5), 0.8) * e.astype(np.float32), 15)


# ----------------------------------------------------------------------------
#  Sound effects
# ----------------------------------------------------------------------------
def fx_swing(dur, lo, hi, tone=0.0, body=1.0):
    t = _t(dur)
    nz = fft_filter(noise(dur), lo=lo, hi=hi)
    e = np.sin(np.pi * np.clip(t / dur, 0, 1)) ** 2.0
    y = nz * e * body
    if tone:
        y += np.sin(TAU * np.cumsum(900 + 1800 * (t / dur)) / SR) * e * tone * 0.2
    return fade_tail(norm(y, 0.7))


def fx_hit(power, flesh=1.0, ring=0.3):
    dur = 0.12 + 0.12 * power
    t = _t(dur)
    thump = np.sin(TAU * np.cumsum(60 + 90 * np.exp(-t * 40)) / SR) * np.exp(-t * (30 - 14 * power))
    nz = fft_filter(noise(dur), hi=2500 + 1500 * power) * np.exp(-t * 28)
    sq = fft_filter(noise(dur), hi=700, lo=120) * np.exp(-t * 18) * flesh
    rg = np.zeros_like(t)
    for fr_, a in ((1700, 0.5), (2430, 0.3), (3310, 0.2)):
        rg += np.sin(TAU * fr_ * t) * a * np.exp(-t * 26)
    y = thump * (0.9 + power * 0.6) + nz * 0.7 + sq * 0.8 + rg * ring
    return fade_tail(norm(drive(y, 1.3), 0.85))


def fx_block(power=1.0):
    dur = 0.35
    t = _t(dur)
    y = np.zeros_like(t)
    for fr_, a, d in ((1180, 1.0, 14), (1870, 0.7, 17), (2630, 0.5, 22), (3350, 0.35, 25), (4410, 0.2, 30)):
        y += np.sin(TAU * fr_ * t + np.sin(TAU * 7 * t) * 0.3) * a * np.exp(-t * d)
    y += fft_filter(noise(dur), lo=2000) * np.exp(-t * 60) * 0.8
    y += np.sin(TAU * 90 * t) * np.exp(-t * 35) * 0.6 * power
    return fade_tail(norm(y, 0.8))


def fx_clash():
    dur = 0.9
    t = _t(dur)
    y = np.zeros_like(t)
    for fr_, a, d in ((860, 1.0, 5), (1370, 0.8, 6), (2210, 0.7, 8), (3170, 0.5, 11), (4630, 0.35, 14), (6100, 0.2, 18)):
        y += np.sin(TAU * fr_ * t + np.sin(TAU * 11 * t) * 0.5) * a * np.exp(-t * d)
    y += fft_filter(noise(dur), lo=1500) * np.exp(-t * 30) * 1.0
    y += np.sin(TAU * np.cumsum(70 + 80 * np.exp(-t * 20)) / SR) * np.exp(-t * 9) * 1.1
    return fade_tail(norm(drive(y, 1.4), 0.9), 20)


def fx_parry():
    dur = 0.7
    t = _t(dur)
    y = np.sin(TAU * np.cumsum(2200 + 3200 * np.exp(-t * 14)) / SR) * np.exp(-t * 9)
    for fr_, a in ((3300, 0.5), (4900, 0.4), (6600, 0.3)):
        y += np.sin(TAU * fr_ * t) * a * np.exp(-t * 7)
    y += fft_filter(noise(dur), lo=5000) * np.exp(-t * 20) * 0.7
    y += np.sin(TAU * 120 * t) * np.exp(-t * 25) * 0.5
    return fade_tail(norm(echo(y, 0.07, 0.35, 2)[:int(dur * SR)], 0.85), 20)


def fx_guardbreak():
    dur = 0.9
    t = _t(dur)
    y = fft_filter(noise(dur), lo=2500) * np.exp(-t * 6)
    for i in range(14):
        fr_ = _RNG.uniform(2000, 7000)
        s = int(_RNG.uniform(0, 0.25) * SR)
        part = np.sin(TAU * fr_ * t[:len(t) - s]) * np.exp(-t[:len(t) - s] * 18) * 0.3
        y[s:] += part
    y += np.sin(TAU * np.cumsum(120 - 70 * t) / SR) * np.exp(-t * 6) * 1.2
    return fade_tail(norm(drive(y, 1.2), 0.9), 20)


def fx_proj(kind='c'):
    dur = 0.8
    t = _t(dur)
    if kind == 'c':
        f = 70 + 220 * np.sin(np.pi * t / dur)
        y = drive(np.sin(TAU * np.cumsum(f) / SR) + 0.6 * ((np.cumsum(f) / SR) % 1 * 2 - 1), 2.5)
        y += fft_filter(noise(dur), lo=300, hi=2500) * 0.5 * np.sin(np.pi * t / dur)
        y *= np.sin(np.pi * np.clip(t / dur, 0, 1)) ** 0.6
    else:
        f = 1200 + 2400 * (t / dur) ** 1.5
        y = np.sin(TAU * np.cumsum(f) / SR) * 0.4 + fft_filter(noise(dur), lo=2500, hi=9000) * 0.9
        y *= np.sin(np.pi * np.clip(t / dur, 0, 1)) ** 1.2
    return fade_tail(norm(y, 0.7), 20)


def fx_riser(dur=1.4, low=200, high=6000, boom=True):
    t = _t(dur)
    nz = noise(dur)
    y = band(nz, 1000, 500) * 0 + fft_filter(nz, lo=low, hi=high) * (t / dur) ** 2
    y += np.sin(TAU * np.cumsum(low + (high - low) * (t / dur) ** 3) / SR) * 0.25 * (t / dur)
    if boom:
        bt = _t(0.6)
        b = np.sin(TAU * np.cumsum(60 + 40 * np.exp(-bt * 8)) / SR) * np.exp(-bt * 5) * 1.4
        y = np.concatenate([y, np.zeros(len(b), np.float32)])
        y[-len(b):] += b
    return fade_tail(norm(y, 0.9), 20)


def fx_gong():
    dur = 2.6
    t = _t(dur)
    y = np.zeros_like(t)
    for fr_, a, d in ((78, 1.0, 1.4), (117, 0.8, 1.6), (156.5, 0.6, 2.0), (231, 0.45, 2.4), (351, 0.3, 3.0),
                      (477, 0.25, 3.4), (623, 0.18, 4.0), (881, 0.1, 5)):
        y += np.sin(TAU * fr_ * t + np.sin(TAU * 2.3 * t) * 1.2) * a * np.exp(-t * d)
    y += fft_filter(noise(dur), lo=600, hi=5000) * np.exp(-t * 7) * 0.3
    return fade_tail(norm(y, 0.9), 40)


def fx_curse():
    dur = 0.9
    t = _t(dur)
    y = np.sin(TAU * np.cumsum(220 + 4 * np.sin(TAU * 6 * t)) / SR) * 0.4
    y += np.sin(TAU * np.cumsum(311 + 6 * np.sin(TAU * 5 * t)) / SR) * 0.3
    y += band(noise(dur), 1800, 600) * 0.8 * (np.sin(TAU * 9 * t) * 0.5 + 0.5)
    y += band(noise(dur), 3200, 1000) * 0.4
    y *= np.sin(np.pi * np.clip(t / dur, 0, 1)) ** 0.7
    return fade_tail(norm(y, 0.7), 20)


def fx_stance():
    dur = 0.55
    t = _t(dur)
    nz = band(noise(dur), 3500, 1500) * np.minimum(t / 0.2, 1) * np.exp(-t * 2)
    ring = np.sin(TAU * np.cumsum(2400 + 1800 * t / dur) / SR) * np.exp(-t * 7) * 0.4
    return fade_tail(norm(nz + ring, 0.7), 20)


def fx_sheath():
    t = _t(0.25)
    y = fft_filter(noise(0.25), lo=2200) * np.exp(-t * 40) * 0.7
    y += np.sin(TAU * 1600 * t) * np.exp(-t * 28) * 0.5 + np.sin(TAU * 240 * t) * np.exp(-t * 60) * 0.7
    return fade_tail(norm(y, 0.75))


def fx_fox():
    dur = 0.5
    t = _t(dur)
    y = s_bell(88, dur, 1.6, 2.0) * 0.8
    y += fft_filter(noise(dur), lo=3000, hi=8000) * np.sin(np.pi * np.clip(t / dur, 0, 1)) * 0.5
    y += np.sin(TAU * np.cumsum(500 + 2600 * (t / dur) ** 2) / SR) * 0.15 * np.sin(np.pi * np.clip(t / dur, 0, 1))
    return fade_tail(norm(y, 0.7), 20)


def fx_ko():
    dur = 2.2
    t = _t(dur)
    y = np.sin(TAU * np.cumsum(55 + 140 * np.exp(-t * 3)) / SR) * np.exp(-t * 1.6) * 1.2
    y += fft_filter(noise(dur), hi=1800) * np.exp(-t * 4) * 0.9
    y += s_bell(52, dur, 3.0, 1.4)[:len(t)] * 0.0 if False else 0
    for fr_, a in ((440, 0.3), (660, 0.2), (831, 0.15)):
        y += np.sin(TAU * fr_ * t) * a * np.exp(-t * 3)
    return fade_tail(norm(echo(y, 0.13, 0.4, 3)[:len(t)], 0.95), 40)


def fx_rage():
    dur = 1.3
    t = _t(dur)
    y = np.zeros_like(t)
    for b in (0.0, 0.3):
        s = int(b * SR)
        k = s_kick(1.3, 0.35, 38)
        y[s:s + len(k)] += k[:len(y) - s] * 1.0
    g = drive(saw(48, dur) * 0.6 + saw(48.7, dur) * 0.6, 3) * np.sin(np.pi * np.clip(t / dur, 0, 1)) * 0.6
    y += fft_filter(g, hi=900)
    return fade_tail(norm(y, 0.9), 30)


def fx_ui(kind):
    if kind == 'move':
        t = _t(0.07)
        return fade_tail(norm(np.sin(TAU * 880 * t) * np.exp(-t * 40) + np.sin(TAU * 1320 * t) * np.exp(-t * 55) * 0.5, 0.5))
    if kind == 'ok':
        a = s_bell(81, 0.5, 1.5, 2.0)
        b = s_bell(88, 0.5, 1.5, 2.0)
        out = np.zeros(int(0.5 * SR), np.float32)
        out[:len(a)] += a[:len(out)]
        s = int(0.07 * SR)
        out[s:] += b[:len(out) - s]
        return norm(out, 0.6)
    if kind == 'back':
        t = _t(0.18)
        return fade_tail(norm(np.sin(TAU * np.cumsum(700 - 400 * t / 0.18) / SR) * np.exp(-t * 14), 0.5))
    t = _t(0.1)
    return fade_tail(norm(np.sin(TAU * 440 * t) * np.exp(-t * 25), 0.4))


def fx_cloth(dur=0.14, lo=500, hi=3500, amp=0.4):
    t = _t(dur)
    return fade_tail(fft_filter(noise(dur), lo=lo, hi=hi) * np.sin(np.pi * np.clip(t / dur, 0, 1)) * amp)


def fx_land():
    t = _t(0.16)
    y = np.sin(TAU * np.cumsum(90 + 40 * np.exp(-t * 30)) / SR) * np.exp(-t * 22) + fft_filter(noise(0.16), hi=900) * np.exp(-t * 30) * 0.6
    return fade_tail(norm(y, 0.6))


def fx_blood():
    dur = 0.35
    t = _t(dur)
    y = fft_filter(noise(dur), lo=300, hi=2200) * np.exp(-t * 12)
    for i in range(7):
        s = int(_RNG.uniform(0.0, 0.2) * SR)
        f = _RNG.uniform(200, 700)
        part = np.sin(TAU * np.cumsum(f + 600 * np.exp(-t[:len(t) - s] * 40)) / SR) * np.exp(-t[:len(t) - s] * 60) * 0.4
        y[s:] += part
    return fade_tail(norm(y, 0.6))


def fx_beam(dur=1.0):
    t = _t(dur)
    y = drive(saw(55, dur) * 0.6 + saw(110.7, dur) * 0.4, 3) * np.sin(np.pi * np.clip(t / dur, 0, 1)) ** 0.5
    y += fft_filter(noise(dur), lo=1500, hi=9000) * np.sin(np.pi * np.clip(t / dur, 0, 1)) * 0.6
    return fade_tail(norm(y, 0.8), 30)


# ----------------------------------------------------------------------------
#  Music composition
# ----------------------------------------------------------------------------
class Song:
    def __init__(self, bpm, bars, spb=16):
        self.bpm = bpm
        self.bars = bars
        self.spb = spb
        self.step = 60.0 / bpm / 4.0
        self.steps = bars * spb
        self.N = int(self.steps * self.step * SR)
        self.buf = np.zeros((self.N, 2), np.float32)

    def at(self, step):
        return int(step * self.step * SR)

    def put(self, snd, step, gain=1.0, pan=0.0):
        mixin(self.buf, snd, self.at(step), gain, pan)

    def layer(self):
        return np.zeros((self.N, 2), np.float32)

    def put_to(self, layer, snd, step, gain=1.0, pan=0.0):
        mixin(layer, snd, self.at(step), gain, pan)

    def duck(self, kick_steps, depth=0.75, rel=0.16):
        e = np.ones(self.N, np.float32)
        for s in kick_steps:
            a = self.at(s)
            n = int(rel * SR * 1.6)
            c = np.arange(min(n, self.N - a)) / SR
            if len(c) <= 0:
                continue
            curve = 1 - depth * np.exp(-c / (rel * 0.5))
            e[a:a + len(c)] = np.minimum(e[a:a + len(c)], curve)
        return e

    def finish(self, limit=0.92):
        x = self.buf
        x = x / max(1e-6, float(np.max(np.abs(x))))
        x = np.tanh(x * 1.5) / np.tanh(1.5)
        return x * limit


def _pat(s):
    return [c for c in s.replace(' ', '')]


def build_fight_song():
    sg = Song(174, 16)
    kick = s_kick(1.15)
    kick2 = s_kick(0.9, 0.22, 52)
    snare = s_snare()
    ghost = s_snare(0.12, 210, 0.45)
    clap = s_clap()
    hat = s_hat()
    hat_o = s_hat(True)
    crash = s_crash()
    tom = s_tom(95)
    tom2 = s_tom(135)
    drums = sg.layer()
    kick_steps = []
    BK = _pat("x.x. .... ..x. ..x.")
    BS = _pat(".... x..g .g.. x..g")
    BK2 = _pat("x... x... x... x..x")
    BH = _pat("x.xx x.xx x.x. x.xx")
    FK = _pat("x... x... x... x...")
    for bar in range(16):
        sec = bar // 4
        base = bar * 16
        for i in range(16):
            st = base + i
            sk = False
            if sec == 0:
                if BK[i] == 'x':
                    sg.put_to(drums, kick, st, 0.95); sk = True
                if BS[i] == 'x':
                    sg.put_to(drums, snare, st, 0.85)
                elif BS[i] == 'g':
                    sg.put_to(drums, ghost, st, 0.5)
                if BH[i] == 'x':
                    sg.put_to(drums, hat, st, 0.35 + 0.1 * (i % 4 == 0), pan=0.2 if i % 2 else -0.2)
            elif sec == 1:
                if FK[i] == 'x':
                    sg.put_to(drums, kick, st, 1.0); sk = True
                if i in (4, 12):
                    sg.put_to(drums, snare, st, 0.8)
                    sg.put_to(drums, clap, st, 0.5)
                if i in (2, 6, 10, 14):
                    sg.put_to(drums, hat_o, st, 0.4)
                if BH[i] == 'x' and i % 2 == 1:
                    sg.put_to(drums, hat, st, 0.3)
                if i in (7, 9) and bar % 2 == 1:
                    sg.put_to(drums, ghost, st, 0.55)
            elif sec == 2:
                if i == 0 or (i == 10 and bar % 2 == 0):
                    sg.put_to(drums, kick, st, 1.0); sk = True
                if i == 8:
                    sg.put_to(drums, snare, st, 0.9)
                    sg.put_to(drums, clap, st, 0.6)
                if i % 4 == 2:
                    sg.put_to(drums, hat, st, 0.3)
                if bar == 11 and i >= 8:
                    sg.put_to(drums, snare if i % 2 == 0 else ghost, st, 0.4 + (i - 8) * 0.08)
                    if i == 8:
                        sg.put_to(drums, tom, st, 0.6)
            else:
                if BK2[i] == 'x':
                    sg.put_to(drums, kick, st, 1.05); sk = True
                if i in (4, 12):
                    sg.put_to(drums, snare, st, 0.95)
                    sg.put_to(drums, clap, st, 0.45)
                if BS[i] == 'g':
                    sg.put_to(drums, ghost, st, 0.5)
                if i % 2 == 1:
                    sg.put_to(drums, hat, st, 0.33)
                if i in (2, 10):
                    sg.put_to(drums, hat_o, st, 0.38)
                if i in (6, 14) and bar % 2 == 0:
                    sg.put_to(drums, kick2, st, 0.7); sk = True
            if sk:
                kick_steps.append(st)
        if bar % 4 == 3 and sec != 2:
            for i in range(8, 16):
                sg.put_to(drums, snare if i % 2 == 0 else ghost, base + i, 0.45 + (i - 8) * 0.07)
            sg.put_to(drums, tom2, base + 14, 0.7)
        if bar % 4 == 0:
            sg.put(crash, base, 0.55)
    duck = sg.duck(kick_steps)

    # ---- bass: rolling distorted 16ths (F# phrygian)
    bassl = sg.layer()
    roots = [0, 1, 0, -2]
    rif_a = [0, None, 0, 0, 12, None, 0, None, 0, 0, 1, None, 0, None, 3, None]
    rif_b = [0, 0, None, 12, 0, None, 0, 7, None, 0, 0, None, 10, None, 8, None]
    rif_c = [0, None, None, None, 0, None, None, 0, None, None, 0, None, 3, None, 1, None]
    for bar in range(16):
        sec = bar // 4
        r = roots[bar % 4]
        rf = rif_c if sec == 2 else (rif_a if bar % 2 == 0 else rif_b)
        if sec == 3 and bar % 4 == 3:
            rf = rif_b
        for i, n in enumerate(rf):
            if n is None:
                continue
            m = 30 + r + n
            acc = (i % 4 == 0)
            snd = s_bass(m, 0.16 if sec != 2 else 0.4, acc, 620 if sec != 3 else 900)
            sg.put_to(bassl, snd, bar * 16 + i, 0.78 if acc else 0.6)
    # ---- pad (choir) : sections 0 + 2 strong
    padl = sg.layer()
    for bar in range(16):
        sec = bar // 4
        if sec == 1:
            continue
        r = roots[bar % 4]
        dur = 16 * sg.step + 0.4
        notes = [42 + r, 45 + r, 49 + r] if (bar % 4) != 1 else [43 + r, 46 + r, 50 + r]
        x = np.zeros(int(dur * SR), np.float32)
        for m in notes:
            x += saw(mtof(m), dur, 0.004) + saw(mtof(m) * 1.007, dur) * 0.7
        x = fit(x, int(dur * SR))
        # choir-ish formant colouring
        X = np.fft.rfft(x)
        fr = np.fft.rfftfreq(len(x), 1 / SR)
        m_ = 0.05 + np.exp(-0.5 * ((fr - 750) / 160) ** 2) + 0.6 * np.exp(-0.5 * ((fr - 1180) / 200) ** 2) + 0.3 * np.exp(-0.5 * ((fr - 2800) / 300) ** 2)
        x = np.fft.irfft(X * m_, len(x)).astype(np.float32)
        x = norm(x, 0.5) * np.minimum(np.arange(len(x)) / (0.25 * SR), 1.0)
        sg.put_to(padl, x, bar * 16, 0.55 if sec == 2 else 0.35)
    # ---- lead stabs / riff
    leadl = sg.layer()
    mel = {
        1: [(0, 0, 2), (3, 1, 1), (4, 0, 2), (7, 3, 1), (8, 7, 2), (10, 3, 1), (12, 1, 2), (14, 0, 2)],
        3: [(0, 12, 3), (3, 13, 1), (4, 12, 2), (6, 15, 2), (8, 19, 3), (11, 15, 1), (12, 13, 2), (14, 12, 2)],
    }
    for bar in range(16):
        sec = bar // 4
        if sec not in mel:
            continue
        r = roots[bar % 4]
        for (st, off, ln) in mel[sec]:
            snd = s_stab(54 + r + off, ln * sg.step + 0.1, 3600, 0.007, 0.01)
            sg.put_to(leadl, snd, bar * 16 + st, 0.5, pan=0.15)
            sg.put_to(leadl, snd, bar * 16 + st + 0.4, 0.18, pan=-0.3)
    # ---- bell arpeggios (sec 2/3)
    belll = sg.layer()
    arp = [0, 7, 12, 15, 19, 15, 12, 7]
    for bar in range(16):
        sec = bar // 4
        if sec < 2:
            continue
        r = roots[bar % 4]
        for i in range(0, 16, 2):
            m = 66 + r + arp[(i // 2) % 8] + (12 if (sec == 3 and i % 8 == 6) else 0)
            sg.put_to(belll, s_bell(m, 0.7), bar * 16 + i, 0.25 if sec == 2 else 0.17, pan=0.4 if (i // 2) % 2 else -0.4)
    # ---- risers
    fxl = sg.layer()
    riser = fx_riser(4 * 4 * sg.step * 0.95, 300, 7000, boom=False)
    sg.put_to(fxl, riser, 16 * 3 - 12 + 0, 0.5)         # into section 1
    sg.put_to(fxl, riser, 16 * 11 + 0, 0.45)            # into drop
    sg.put_to(fxl, riser, 16 * 15, 0.35)
    for (sa, g) in ((64, 0.6), (128, 0.7), (192, 0.9)):
        sg.put_to(fxl, s_kick(1.3, 0.5, 34), sa, g)
    sg.buf += drums * 0.95
    sg.buf += bassl * 0.9 * duck[:, None]
    sg.buf += padl * 0.85 * duck[:, None] ** 0.5
    sg.buf += leadl * 0.8
    sg.buf += belll * 0.9
    sg.buf += fxl * 0.7
    return sg.finish(0.9)


def build_title_song():
    sg = Song(140, 16)
    kick = s_kick(1.2, 0.34, 40)
    snare = s_snare(0.3, 170)
    ghost = s_snare(0.1, 200, 0.4)
    hat = s_hat()
    hat_o = s_hat(True)
    crash = s_crash(2.4)
    clap = s_clap()
    tom = s_tom(80, 0.4)
    drums = sg.layer()
    kicks = []
    for bar in range(16):
        base = bar * 16
        if bar >= 4:
            pk = "x......x..x....." if bar % 2 == 0 else "x.....x...x...x."
            for i, c in enumerate(pk):
                if c == 'x':
                    sg.put_to(drums, kick, base + i, 1.0); kicks.append(base + i)
            for i in (8,):
                sg.put_to(drums, snare, base + i, 0.95)
                sg.put_to(drums, clap, base + i, 0.5)
            if bar >= 8:
                for i in range(0, 16, 2):
                    sg.put_to(drums, hat, base + i, 0.3)
                for i in (7, 13, 15):
                    sg.put_to(drums, ghost, base + i, 0.5)
                sg.put_to(drums, hat_o, base + 6, 0.35)
                sg.put_to(drums, hat_o, base + 14, 0.35)
            if bar % 4 == 3:
                for i in range(10, 16):
                    sg.put_to(drums, snare if i % 2 == 0 else ghost, base + i, 0.4 + (i - 10) * 0.1)
                sg.put_to(drums, tom, base + 12, 0.7)
        if bar % 4 == 0:
            sg.put(crash, base, 0.6)
    duck = sg.duck(kicks, 0.6, 0.2)
    roots = [38, 34, 31, 33]       # Dm  Bb  Gm  A
    padl = sg.layer()
    for bar in range(16):
        r = roots[bar % 4]
        dur = 16 * sg.step + 0.5
        minor = (bar % 4) != 3
        chord = [r + 12, r + 15 if minor else r + 16, r + 19, r + 24]
        x = np.zeros(int(dur * SR), np.float32)
        for m in chord:
            x += saw(mtof(m), dur, 0.005) + saw(mtof(m) * 1.006, dur) * 0.8
        X = np.fft.rfft(x)
        fr = np.fft.rfftfreq(len(x), 1 / SR)
        m_ = 0.04 + np.exp(-0.5 * ((fr - 620) / 140) ** 2) + 0.7 * np.exp(-0.5 * ((fr - 1050) / 180) ** 2) + 0.35 * np.exp(-0.5 * ((fr - 2600) / 300) ** 2)
        x = np.fft.irfft(X * m_, len(x)).astype(np.float32)
        x = norm(x, 0.55) * np.minimum(np.arange(len(x)) / (0.5 * SR), 1.0)
        sg.put_to(padl, x, bar * 16, 0.6)
    bassl = sg.layer()
    for bar in range(4, 16):
        r = roots[bar % 4] - 12
        pat = [0, None, 0, None, 12, None, 0, 0, None, 0, None, 7, None, None, 5, None]
        for i, n in enumerate(pat):
            if n is None:
                continue
            sg.put_to(bassl, s_bass(r + n, 0.2 if i % 4 else 0.3, i % 4 == 0, 560, 3.2), bar * 16 + i, 0.7)
    leadl = sg.layer()
    # gothic bell melody (D minor harmonic)
    melody = [
        (0, 74, 6), (6, 77, 2), (8, 76, 4), (12, 74, 4),
        (16, 70, 6), (22, 74, 2), (24, 73, 4), (28, 70, 4),
        (32, 67, 6), (38, 70, 2), (40, 69, 4), (44, 67, 4),
        (48, 69, 4), (52, 73, 4), (56, 76, 4), (60, 77, 4),
    ]
    for rep in range(4):
        for (st, m, ln) in melody:
            s = rep * 64 + st
            if s >= 16 * 16:
                continue
            if rep == 0:
                sg.put_to(leadl, s_bell(m + 0, 1.2, 2.2, 3.0), s, 0.5, pan=0.2)
            else:
                snd = s_stab(m, ln * sg.step + 0.15, 2600, 0.005, 0.02)
                sg.put_to(leadl, snd, s, 0.38, pan=-0.1)
                sg.put_to(leadl, s_bell(m + 12, 0.8, 2.2, 3.0), s, 0.18, pan=0.3)
    arpl = sg.layer()
    for bar in range(8, 16):
        r = roots[bar % 4] + 36
        minor = (bar % 4) != 3
        pat = [0, 3 if minor else 4, 7, 12]
        for i in range(0, 16, 2):
            sg.put_to(arpl, s_bell(r + pat[(i // 2) % 4], 0.45, 1.8, 3.5), bar * 16 + i, 0.16, pan=0.5 if (i // 2) % 2 else -0.5)
    fxl = sg.layer()
    sg.put_to(fxl, fx_riser(sg.step * 16 * 0.98, 200, 6000, boom=False), 16 * 3, 0.6)
    sg.put_to(fxl, fx_riser(sg.step * 16 * 0.98, 200, 6000, boom=False), 16 * 7, 0.6)
    sg.put_to(fxl, fx_riser(sg.step * 16 * 0.98, 200, 6000, boom=False), 16 * 15, 0.6)
    sg.buf += drums * 0.95 + bassl * 0.85 * duck[:, None] + padl * 0.8 * duck[:, None] ** 0.5 + leadl * 0.85 + arpl + fxl * 0.7
    return sg.finish(0.9)


# ----------------------------------------------------------------------------
#  Audio manager
# ----------------------------------------------------------------------------
class Audio:
    def __init__(self):
        self.ok = False
        self.sfx = {}
        self.music = {}
        self.music_name = None
        self.music_ch = None
        self.ready = False

    def init(self):
        try:
            pygame.mixer.pre_init(SR, -16, 2, 512)
            pygame.mixer.init(SR, -16, 2, 512)
            pygame.mixer.set_num_channels(28)
            self.music_ch = pygame.mixer.Channel(0)
            self.ok = True
        except Exception as e:  # no audio device
            print('Audio disabled:', e)
            self.ok = False

    def build(self, progress=None):
        if not self.ok:
            self.ready = True
            return
        S = self.sfx
        jobs = []

        def add(name, fn, gain=1.0, pan=0.0):
            jobs.append((name, fn, gain, pan))
        add('swing_l', lambda: fx_swing(0.16, 900, 6500, 0.4), 0.7)
        add('swing_h', lambda: fx_swing(0.28, 400, 5000, 0.5, 1.2), 0.85)
        add('swing_k', lambda: fx_swing(0.18, 600, 4000, 0.2), 0.7)
        add('swing_x', lambda: fx_swing(0.5, 200, 7000, 0.8, 1.4), 0.9)
        add('hit_l', lambda: fx_hit(0.3), 0.9)
        add('hit_m', lambda: fx_hit(0.6), 1.0)
        add('hit_h', lambda: fx_hit(1.0, 1.3, 0.4), 1.1)
        add('hit_k', lambda: fx_hit(0.5, 0.6, 0.0), 0.95)
        add('blood', fx_blood, 0.8)
        add('block', fx_block, 0.9)
        add('clash', fx_clash, 1.1)
        add('parry', fx_parry, 1.0)
        add('guardbreak', fx_guardbreak, 1.0)
        add('proj_c', lambda: fx_proj('c'), 0.9)
        add('proj_k', lambda: fx_proj('k'), 0.8)
        add('riser', lambda: fx_riser(1.2, 200, 7000), 1.0)
        add('gong', fx_gong, 1.0)
        add('curse', fx_curse, 0.8)
        add('stance', fx_stance, 0.8)
        add('sheath', fx_sheath, 0.8)
        add('fox', fx_fox, 0.8)
        add('ko', fx_ko, 1.1)
        add('rage', fx_rage, 1.0)
        add('beam', fx_beam, 0.9)
        add('jump', lambda: fx_cloth(0.16, 400, 3000, 0.5), 0.7)
        add('dash', lambda: fx_cloth(0.22, 300, 2500, 0.7), 0.8)
        add('land', fx_land, 0.7)
        add('step', lambda: fx_cloth(0.07, 200, 1800, 0.4), 0.35)
        add('ui_move', lambda: fx_ui('move'), 0.6)
        add('ui_ok', lambda: fx_ui('ok'), 0.7)
        add('ui_back', lambda: fx_ui('back'), 0.6)
        add('ui_tick', lambda: fx_ui('tick'), 0.5)
        add('kiai_c', lambda: voice(120, 0.3, 'a', 80, 0.55, 0.01, d=2.5) * 0.9 + voice(60, 0.3, 'o', 45, 0.7, 0.0) * 0.5, 0.9)
        add('kiai_c2', lambda: voice(140, 0.4, 'o', 70, 0.6, 0.02, vowel2='a', d=2.0), 0.9)
        add('kiai_k', lambda: voice(360, 0.22, 'e', 300, 0.25, 0.02, vowel2='a', d=2.0), 0.9)
        add('kiai_k2', lambda: voice(430, 0.28, 'i', 330, 0.2, 0.03, vowel2='a', d=2.2), 0.9)
        add('hurt_c', lambda: voice(190, 0.28, 'a', 110, 0.5, 0.03, d=2.5), 0.9)
        add('hurt_k', lambda: voice(470, 0.26, 'e', 300, 0.3, 0.04, vowel2='a', d=2.2), 0.9)
        add('ko_c', lambda: voice(210, 1.0, 'a', 70, 0.6, 0.05, vowel2='o', d=2.0), 0.95)
        add('ko_k', lambda: voice(520, 0.9, 'e', 190, 0.35, 0.06, vowel2='o', d=2.0), 0.95)
        add('ult_c', lambda: echo(voice(85, 0.9, 'a', 60, 0.8, 0.0, vowel2='o', d=1.5), 0.12, 0.4, 3), 1.0)
        add('ult_k', lambda: echo(voice(400, 0.6, 'i', 520, 0.15, 0.03, vowel2='a', d=1.8), 0.1, 0.45, 3), 1.0)
        add('win_c', lambda: np.concatenate([voice(150, 0.18, 'a', 120, 0.5, 0.0, d=3) for _ in range(3)] + [np.zeros(int(0.05 * SR), np.float32)]), 0.9)
        add('win_k', lambda: np.concatenate([voice(380 + 70 * i, 0.14, 'i', 420 + 70 * i, 0.15, 0.02, d=3) for i in range(3)]), 0.9)
        add('fight', lambda: echo(drive(voice(100, 0.55, 'a', 85, 0.7, 0.0, vowel2='i', d=1.3), 1.4), 0.1, 0.4, 3), 1.0)
        add('whisper', lambda: fft_filter(noise(0.9), lo=1800, hi=6000) * np.sin(np.pi * np.clip(_t(0.9) / 0.9, 0, 1)) * 0.5, 0.7)
        n_total = len(jobs) + 2
        for i, (name, fn, gain, pan) in enumerate(jobs):
            try:
                x = fn().astype(np.float32)
                S[name] = to_sound(stereo(norm(x, 0.9), pan), gain)
            except Exception as e:
                print('sfx fail', name, e)
            if progress:
                progress((i + 1) / n_total, 'Forging sounds')
        self.music['title'] = to_sound(build_title_song(), 1.0)
        if progress:
            progress((len(jobs) + 1) / n_total, 'Composing overture')
        self.music['fight'] = to_sound(build_fight_song(), 1.0)
        if progress:
            progress(1.0, 'Composing carnage')
        self.ready = True

    def play(self, name, vol=1.0, pan=0.0):
        if not self.ok:
            return
        s = self.sfx.get(name)
        if s is None:
            return
        ch = s.play()
        if ch is not None:
            v = CFG['sfx_vol'] * vol
            l = v * clamp(1 - pan, 0, 1) if pan > 0 else v
            r = v * clamp(1 + pan, 0, 1) if pan < 0 else v
            ch.set_volume(l, r)

    def play_music(self, name, fade=400):
        if not self.ok or name == self.music_name:
            return
        m = self.music.get(name)
        self.music_name = name
        if m is None:
            return
        self.music_ch.stop()
        self.music_ch.play(m, loops=-1, fade_ms=fade)
        self.music_ch.set_volume(CFG['music_vol'])

    def stop_music(self, fade=500):
        if self.ok and self.music_ch:
            self.music_ch.fadeout(fade)
        self.music_name = None

    def duck_music(self, v):
        if self.ok and self.music_ch:
            self.music_ch.set_volume(CFG['music_vol'] * v)

    def refresh_volume(self):
        if self.ok and self.music_ch:
            self.music_ch.set_volume(CFG['music_vol'])


AUDIO = Audio()

# ============================================================================
#  VECTOR CANVAS  -  supersampled shaded vector drawing used to paint sprites
# ============================================================================
LIGHT = vnorm((-0.45, -0.89))          # direction TOWARD the key light (canvas space)
OUTLINE_W = 0.85                       # outline thickness in sprite units

_soft_cache = {}


def soft_blob(r, col):
    key = (int(r), col)
    s = _soft_cache.get(key)
    if s is None:
        s = radial_alpha(max(2, int(r)), col, 1.6, 255)
        _soft_cache[key] = s
    return s


class Canvas:
    """Draws in sprite units (x right, y down, origin at ground centre)."""

    def __init__(self, mirror=False, k=K_RENDER):
        self.k = k
        self.m = -1.0 if mirror else 1.0
        self.surf = pygame.Surface((int(CANVAS_W * k), int(CANVAS_H * k)), pygame.SRCALPHA)
        self.ox = CANVAS_OX * k
        self.oy = CANVAS_OY * k

    # -- transforms
    def P(self, p):
        return (self.ox + self.m * p[0] * self.k, self.oy + p[1] * self.k)

    def pts(self, ps):
        k, m, ox, oy = self.k, self.m, self.ox, self.oy
        return [(ox + m * p[0] * k, oy + p[1] * k) for p in ps]

    # -- primitives
    def poly(self, ps, col, ol=None, ow=OUTLINE_W):
        pp = self.pts(ps)
        if len(pp) < 3:
            return
        if ol:
            pygame.draw.polygon(self.surf, ol, pp, max(1, int(ow * 2 * self.k)))
        pygame.draw.polygon(self.surf, col, pp)
        if ol:
            pygame.draw.polygon(self.surf, ol, pp, max(1, int(ow * self.k)))

    def circle(self, c, r, col, ol=None, ow=OUTLINE_W):
        p = self.P(c)
        if ol:
            pygame.draw.circle(self.surf, ol, p, max(1, int((r + ow) * self.k)))
        pygame.draw.circle(self.surf, col, p, max(1, int(r * self.k)))

    def ellipse(self, c, rx, ry, col, ang=0.0, ol=None, ow=OUTLINE_W, n=18):
        pts = []
        ca, sa = math.cos(math.radians(ang)), math.sin(math.radians(ang))
        for i in range(n):
            t = TAU * i / n
            x, y = rx * math.cos(t), ry * math.sin(t)
            pts.append((c[0] + x * ca - y * sa, c[1] + x * sa + y * ca))
        self.poly(pts, col, ol, ow)

    def line(self, a, b, col, w=1.0):
        pygame.draw.line(self.surf, col, self.P(a), self.P(b), max(1, int(w * self.k)))

    def pline(self, ps, col, w=1.0, closed=False):
        pp = self.pts(ps)
        if len(pp) > 1:
            pygame.draw.lines(self.surf, col, closed, pp, max(1, int(w * self.k)))

    def apoly(self, ps, rgba):
        """Alpha-blended polygon."""
        pp = self.pts(ps)
        if len(pp) < 3:
            return
        xs = [p[0] for p in pp]
        ys = [p[1] for p in pp]
        x0, y0 = int(min(xs)) - 1, int(min(ys)) - 1
        x1, y1 = int(max(xs)) + 2, int(max(ys)) + 2
        w, h = x1 - x0, y1 - y0
        if w <= 0 or h <= 0 or w > 3000 or h > 3000:
            return
        tmp = pygame.Surface((w, h), pygame.SRCALPHA)
        pygame.draw.polygon(tmp, rgba, [(x - x0, y - y0) for x, y in pp])
        self.surf.blit(tmp, (x0, y0))

    def soft(self, pos, r, col, alpha=255):
        """Soft radial glow blob (alpha blended into the sprite)."""
        b = soft_blob(r * self.k, col)
        if alpha < 255:
            b = b.copy()
            b.fill((255, 255, 255, alpha), special_flags=pygame.BLEND_RGBA_MULT)
        p = self.P(pos)
        self.surf.blit(b, (p[0] - b.get_width() // 2, p[1] - b.get_height() // 2))

    # -- shaded shapes
    def ball(self, c, r, dark, base, hi=None, ol=None, rim=None):
        if ol:
            self.circle(c, r, ol, None)
            r2 = r - OUTLINE_W * 0.6
        else:
            r2 = r
        p = self.P(c)
        kr = r2 * self.k
        pygame.draw.circle(self.surf, dark, p, max(1, int(kr)))
        q = (p[0] + LIGHT[0] * kr * 0.16, p[1] + LIGHT[1] * kr * 0.16)
        pygame.draw.circle(self.surf, base, q, max(1, int(kr * 0.82)))
        if hi:
            q2 = (p[0] + LIGHT[0] * kr * 0.38, p[1] + LIGHT[1] * kr * 0.38)
            pygame.draw.circle(self.surf, hi, q2, max(1, int(kr * 0.34)))
        if rim:
            pygame.draw.arc(self.surf, rim, (p[0] - kr, p[1] - kr, 2 * kr, 2 * kr), math.radians(-30), math.radians(70), max(1, int(kr * 0.1)))

    def _band(self, P, half, shift):
        """Polygon around canvas-space path P with per-point half-width & shift."""
        n = len(P)
        L, R = [], []
        for i in range(n):
            a = P[max(i - 1, 0)]
            b = P[min(i + 1, n - 1)]
            tx, ty = b[0] - a[0], b[1] - a[1]
            d = math.hypot(tx, ty) or 1.0
            nx, ny = -ty / d, tx / d
            h = half[i]
            s = shift[i]
            L.append((P[i][0] + nx * (s + h), P[i][1] + ny * (s + h)))
            R.append((P[i][0] + nx * (s - h), P[i][1] + ny * (s - h)))
        return L + R[::-1]

    def strip(self, path, widths, dark, base, hi=None, ol=None, rim=None, smooth=4, caps=True, ow=OUTLINE_W):
        """Shaded tapered strip along a path (unit coords).  widths: (w0, w1) or list."""
        if smooth and len(path) > 2:
            path = catmull(path, smooth)
        n = len(path)
        if not isinstance(widths, (tuple, list)):
            ws = [widths] * n
        else:
            m = len(widths)
            ws = []
            for i in range(n):
                t = i / max(1, n - 1) * (m - 1)
                j = min(int(t), m - 2)
                ws.append(lerp(widths[j], widths[j + 1], t - j))
        P = self.pts(path)
        k = self.k
        if n < 2:
            return
        # decide light-facing normal sign from the overall chord
        a, b = P[0], P[-1]
        tx, ty = b[0] - a[0], b[1] - a[1]
        d = math.hypot(tx, ty) or 1.0
        nx, ny = -ty / d, tx / d
        ls = 1.0 if (nx * LIGHT[0] + ny * LIGHT[1]) >= 0 else -1.0
        layers = []
        if ol:
            layers.append((1.0, 0.0, ol, ow * 2.0 + 0.0))
        layers.append((1.0, 0.0, dark, 0.0))
        layers.append((0.72, 0.14 * ls, base, 0.0))
        if hi:
            layers.append((0.30, 0.30 * ls, hi, 0.0))
        for f, off, col, extra in layers:
            half = [w * 0.5 * f * k + extra * k * 0.5 for w in ws]
            shift = [w * off * k for w in ws]
            pg = self._band(P, half, shift)
            if len(pg) >= 3:
                pygame.draw.polygon(self.surf, col, pg)
            if caps:
                for idx in (0, n - 1):
                    pc = P[idx]
                    sx, sy = shift[idx], shift[idx]
                    j = max(idx - 1, 0) if idx else 1
                    tx2, ty2 = P[min(idx + 1, n - 1)][0] - P[max(idx - 1, 0)][0], P[min(idx + 1, n - 1)][1] - P[max(idx - 1, 0)][1]
                    dd = math.hypot(tx2, ty2) or 1.0
                    cx = pc[0] + (-ty2 / dd) * shift[idx]
                    cy = pc[1] + (tx2 / dd) * shift[idx]
                    if half[idx] > 0.5:
                        pygame.draw.circle(self.surf, col, (cx, cy), max(1, int(half[idx])))
        if rim:
            half = [w * 0.07 * k for w in ws]
            shift = [-w * 0.44 * ls * k for w in ws]
            pg = self._band(P, half, shift)
            if len(pg) >= 3:
                pygame.draw.polygon(self.surf, rim, pg)

    def tube(self, a, b, wa, wb, dark, base, hi=None, ol=None, rim=None, caps=True):
        self.strip([a, b], [wa, wb], dark, base, hi, ol, rim, smooth=0, caps=caps)

    def poly_shaded(self, ps, dark, base, hi=None, ol=None, ow=OUTLINE_W):
        pp = self.pts(ps)
        if len(pp) < 3:
            return
        cx = sum(p[0] for p in pp) / len(pp)
        cy = sum(p[1] for p in pp) / len(pp)
        size = max(math.hypot(p[0] - cx, p[1] - cy) for p in pp)
        if ol:
            pygame.draw.polygon(self.surf, ol, pp, max(1, int(ow * 2 * self.k)))
        pygame.draw.polygon(self.surf, dark, pp)

        def scaled(f, sh):
            return [(cx + (p[0] - cx) * f + LIGHT[0] * size * sh, cy + (p[1] - cy) * f + LIGHT[1] * size * sh) for p in pp]
        pygame.draw.polygon(self.surf, base, scaled(0.84, 0.07))
        if hi:
            pygame.draw.polygon(self.surf, hi, scaled(0.46, 0.2))
        if ol:
            pygame.draw.polygon(self.surf, ol, pp, max(1, int(ow * self.k)))

    def lit_normal(self, a, b):
        """Unit-space unit vector perpendicular to a->b, pointing toward the key light."""
        vx, vy = self.m * (b[0] - a[0]), (b[1] - a[1])
        d = math.hypot(vx, vy) or 1.0
        nx, ny = -vy / d, vx / d
        if nx * LIGHT[0] + ny * LIGHT[1] < 0:
            nx, ny = -nx, -ny
        return (self.m * nx, ny)

    def sheen_seg(self, a, b, off, col, w=0.8, alpha=200, t0=0.12, t1=0.88):
        """Specular streak parallel to a->b, shifted toward the light by `off` units."""
        n = self.lit_normal(a, b)
        p0 = (lerp(a[0], b[0], t0) + n[0] * off, lerp(a[1], b[1], t0) + n[1] * off)
        p1 = (lerp(a[0], b[0], t1) + n[0] * off, lerp(a[1], b[1], t1) + n[1] * off)
        self.sheen([p0, p1], col, w, alpha)

    def sheen(self, path, col, w=0.8, alpha=200):
        """Specular streak along path (alpha line)."""
        pp = self.pts(catmull(path, 4) if len(path) > 2 else path)
        if len(pp) < 2:
            return
        xs = [p[0] for p in pp]
        ys = [p[1] for p in pp]
        x0, y0 = int(min(xs)) - 4, int(min(ys)) - 4
        x1, y1 = int(max(xs)) + 5, int(max(ys)) + 5
        tmp = pygame.Surface((x1 - x0, y1 - y0), pygame.SRCALPHA)
        pygame.draw.lines(tmp, (col[0], col[1], col[2], alpha), False, [(x - x0, y - y0) for x, y in pp], max(1, int(w * self.k)))
        self.surf.blit(tmp, (x0, y0))


# ============================================================================
#  POSE AUTHORING
# ============================================================================
POSE_DEFAULT = dict(
    hip=(0, -55), ch=(2, -86), hd=(5, -99),
    ha=(14, -62), hb=(10, -64), fa=(-10, -5), fb=(14, -5),
    tw=0.5, htw=None, sr=0.0, hr=0.0, hw=0.45, hu=0.0, ti=0.0, ex=0,
    ta=0.0, tb=0.0, ksa=-1, ksb=-1, esa=1, esb=1,
    wa=None, wb=None, wl=1.0, g2=False, glow=0.0, sheath=None,
    hairA=None, hairB=None, sk=None, sm=None, sm2=None, fxa=None, tail=None,
    lift=0.0, aura=0.0, back=False,
)


class PoseBook(dict):
    """Registry of authored keyframes.  P(name, **overrides)  - full pose;
    D(name, base, **overrides) - derive a new keyframe from an existing one."""

    def __init__(self, defaults=None):
        super().__init__()
        self.defaults = dict(POSE_DEFAULT)
        if defaults:
            self.defaults.update(defaults)

    def P(self, name, **kw):
        d = dict(self.defaults)
        d.update(kw)
        self[name] = d
        return d

    def D(self, name, base, **kw):
        d = dict(self[base])
        d.update(kw)
        self[name] = d
        return d


# ============================================================================
#  FIGURE BASE  -  skeleton solving + shared body parts
# ============================================================================
SKIN = dict(dark=(205, 150, 148), base=(242, 208, 196), hi=(255, 236, 224), ol=(46, 20, 28), blush=(255, 150, 160))


class Fig:
    UA, FA, TH, SH = 18.0, 17.0, 28.5, 28.0

    def __init__(self, pal):
        self.pal = pal

    # ------------------------------------------------------------------
    def solve(self, p):
        J = {}
        hip, ch, hd = p['hip'], p['ch'], p['hd']
        tw = p['tw']
        htw = p['htw'] if p['htw'] is not None else tw * 0.85
        sg = 1.0 if tw >= 0 else -1.0
        spread = max(1.6, 11.0 * (1 - abs(tw) ** 1.4 * 0.88))
        sp = vnorm(vsub(ch, hip))
        if vlen(sp) < 0.1:
            sp = (0, -1)
        perp = vrot(sp, 90 + p['sr'])                  # upright (0,-1) -> (1, 0)
        down = (-sp[0], -sp[1])
        sh_c = vadd(ch, vmul(down, 3.2))
        J['shA'] = vadd(sh_c, vmul(perp, -sg * spread))
        J['shB'] = vadd(sh_c, vmul(perp, sg * spread))
        hs = max(1.6, 7.4 * (1 - abs(htw) ** 1.4 * 0.88))
        hg = 1.0 if htw >= 0 else -1.0
        hp = vrot((1, 0), p['hr'])
        J['hpA'] = vadd(hip, vmul(hp, -hg * hs))
        J['hpB'] = vadd(hip, vmul(hp, hg * hs))
        # hands (two-handed grip helper)
        ha, hb = p['ha'], p['hb']
        if p['g2'] and p['wa'] is not None:
            d = vdir(p['wa'])
            hb = vsub(ha, vmul(d, 9.5))
        J['elA'], J['haA'] = ik2(J['shA'], ha, self.UA, self.FA, p['esa'])
        J['elB'], J['haB'] = ik2(J['shB'], hb, self.UA, self.FA, p['esb'])
        J['knA'], J['anA'] = ik2(J['hpA'], p['fa'], self.TH, self.SH, p['ksa'])
        J['knB'], J['anB'] = ik2(J['hpB'], p['fb'], self.TH, self.SH, p['ksb'])
        J['neck'] = vadd(ch, (0, 0))
        J['spine'] = sp
        J['perp'] = perp
        J['sg'] = sg
        J['hg'] = hg
        return J

    # ------------------------------------------------------------------
    def render(self, pose, mirror=False):
        c = Canvas(mirror)
        J = self.solve(pose)
        self.paint(c, pose, J)
        return c.surf

    def paint(self, c, p, J):       # overridden
        raise NotImplementedError

    # ------------------------------------------------------------------
    #  shared parts
    # ------------------------------------------------------------------
    def draw_neck(self, c, p, J):
        ch, hd = p['ch'], p['hd']
        top = (hd[0] - 0.5 + p['hw'] * 0.6, hd[1] + 7.5)
        c.tube((ch[0], ch[1] + 1.5), top, 5.2, 4.4, SKIN['dark'], SKIN['base'], None, SKIN['ol'])

    def head_outline(self, p):
        """Face silhouette points relative to head centre (turn aware)."""
        hw = p['hw']
        fo = hw * 3.6
        rr = 8.5 * (1 - 0.16 * max(hw, 0)) + 0.4 * max(-hw, 0)
        rl = 8.5 * (1 - 0.16 * max(-hw, 0)) + 0.4 * max(hw, 0)
        pts = []
        for i in range(0, 11):
            t = math.pi + math.pi * i / 10
            x = math.cos(t)
            pts.append((x * (rl if x < 0 else rr) + fo * 0.15, math.sin(t) * 9.4 - 0.4))
        pts += [(rr + 0.2 + fo * 0.1, 1.0), (rr * 0.9 + fo * 0.35, 5.2), (4.0 + fo * 0.72, 9.0),
                (fo * 0.62 + 0.9, 11.0), (fo * 0.62 - 0.9, 11.0), (-4.0 + fo * 0.5, 9.0), (-rl * 0.9 + fo * 0.1, 5.2), (-rl, 1.0)]
        return pts

    def head_xf(self, p):
        H = p['hd']
        ti = p['ti']
        hu = p['hu']

        def L(x, y):
            v = vrot((x, y + hu * 0.0), ti)
            return (H[0] + v[0], H[1] + v[1])
        return L

    def draw_head_base(self, c, p):
        L = self.head_xf(p)
        pts = [L(*q) for q in self.head_outline(p)]
        c.poly(pts, SKIN['dark'], SKIN['ol'])
        # lit face plane
        hw = p['hw']
        fo = hw * 3.6
        lit = [L(q[0] * 0.9 + fo * 0.2 + 0.6, q[1] * 0.92 - 0.2 + (0.8 if q[1] > 0 else 0)) for q in self.head_outline(p)]
        c.poly(lit, SKIN['base'])
        # cheek / forehead highlight
        c.soft(L(fo * 0.9 - 1.5, -3.5), 4.0, (255, 245, 235), 90)

    def eye(self, c, L, cx, cy, wid, hei, iris, ex, near=True, glow=None, lash=(40, 16, 28), flip=1.0):
        """One almond eye. cx,cy in head space."""
        hl = hei
        if ex in (1, 6):
            hl = hei * 0.62
        if ex in (3, 5):
            hl = 0.4
        top = [L(cx - wid * flip, cy + 0.3), L(cx - wid * 0.45 * flip, cy - hl * 0.95), L(cx + wid * 0.5 * flip, cy - hl * 1.0), L(cx + wid * flip, cy + 0.0)]
        bot = [L(cx + wid * 0.5 * flip, cy + hl * 0.6), L(cx - wid * 0.4 * flip, cy + hl * 0.55)]
        if ex in (3, 5):
            c.pline([L(cx - wid, cy), L(cx, cy + 0.8), L(cx + wid, cy - 0.3)], lash, 0.9)
            return
        c.poly(top + bot, (252, 244, 246), None)
        ir = hl * 0.62 + 0.5
        ic = L(cx + wid * 0.08 * flip, cy + 0.15)
        if glow:
            c.soft(ic, ir * 3.6, glow, 90)
        c.circle(ic, ir, iris[0])
        c.circle(L(cx + wid * 0.08 * flip, cy + 0.35), ir * 0.66, iris[1])
        c.circle(L(cx + wid * 0.08 * flip, cy + 0.15), ir * 0.34, (14, 6, 10))
        c.circle(L(cx - wid * 0.18 * flip, cy - hl * 0.35), 0.46, (255, 255, 255))
        # heavy upper lid line + flick
        c.pline([top[0], top[1], top[2], top[3], L(cx + wid * 1.25 * flip, cy - 0.7)], lash, 1.15)

    def brow(self, c, L, cx, cy, wid, ex, side=1.0, col=(60, 30, 36), flip=1.0):
        """Eyebrow; ex shapes the slant."""
        sl = {0: 0.0, 1: 1.6, 2: 0.6, 3: -0.8, 4: 0.0, 5: -0.5, 6: 0.9}.get(ex, 0.0)
        a = L(cx - wid * 1.1 * flip, cy - 0.5 + sl * 0.5 * side * 0 + (-sl if side > 0 else sl) * 0.0)
        # slant: inner end lower for angry
        inner = (cx - wid * 1.0 * flip, cy + sl * 0.0)
        outer = (cx + wid * 1.1 * flip, cy - sl * 0.2)
        if side > 0:
            inner = (cx - wid * 0.9 * flip, cy + sl * 0.35)
            outer = (cx + wid * 1.1 * flip, cy - sl * 0.25)
        else:
            inner = (cx + wid * 0.9 * flip, cy + sl * 0.35)
            outer = (cx - wid * 1.1 * flip, cy - sl * 0.25)
        c.pline([L(*inner), L((inner[0] + outer[0]) / 2, (inner[1] + outer[1]) / 2 - 0.6), L(*outer)], col, 0.7)

    def mouth(self, c, L, mx, my, ex, lip=(190, 70, 86)):
        if ex == 2:     # shout
            c.poly([L(mx - 3.0, my - 0.8), L(mx, my - 1.4), L(mx + 3.0, my - 0.8), L(mx + 2.2, my + 2.8), L(mx, my + 3.6), L(mx - 2.2, my + 2.8)], (96, 14, 28), (40, 8, 16), 0.5)
            c.poly([L(mx - 2.6, my - 0.7), L(mx + 2.6, my - 0.7), L(mx + 2.4, my + 0.3), L(mx - 2.4, my + 0.3)], (250, 244, 240))
            c.ellipse(L(mx, my + 2.4), 1.7, 0.9, (220, 90, 104))
        elif ex == 1:   # grit
            c.poly([L(mx - 2.6, my - 0.6), L(mx + 2.6, my - 0.6), L(mx + 2.3, my + 1.2), L(mx - 2.3, my + 1.2)], (250, 246, 244), (50, 14, 22), 0.5)
            c.line(L(mx - 2.4, my + 0.3), L(mx + 2.4, my + 0.3), (150, 120, 120), 0.3)
        elif ex == 3:   # pain
            c.pline([L(mx - 2.4, my + 0.8), L(mx - 1.0, my - 0.4), L(mx + 0.6, my + 0.7), L(mx + 2.4, my - 0.3)], (120, 30, 44), 0.9)
        elif ex == 4:   # smirk
            c.pline([L(mx - 2.4, my + 0.1), L(mx, my + 0.9), L(mx + 2.6, my - 0.9)], lip, 0.95)
            c.line(L(mx + 2.6, my - 0.9), L(mx + 3.1, my - 1.4), (120, 40, 54), 0.5)
        elif ex == 5:   # ko
            c.poly([L(mx - 1.8, my), L(mx + 1.8, my), L(mx + 1.4, my + 2.0), L(mx - 1.4, my + 2.0)], (90, 14, 26), (40, 8, 16), 0.4)
        elif ex == 6:   # focus
            c.pline([L(mx - 1.8, my + 0.3), L(mx + 1.8, my + 0.3)], lip, 0.8)
        else:
            c.pline([L(mx - 2.0, my + 0.2), L(mx, my + 0.65), L(mx + 2.0, my + 0.2)], lip, 0.8)

    def draw_hand(self, c, pos, col=None, r=3.5, glove=None, ang=0.0):
        if glove:
            c.ball(pos, r + 0.2, glove[0], glove[1], glove[2], SKIN['ol'])
        else:
            c.ball(pos, r, SKIN['dark'], SKIN['base'], SKIN['hi'], SKIN['ol'])

    # arm skin segment helper
    def arm_skin(self, c, a, b, wa=5.6, wb=4.4):
        c.tube(a, b, wa, wb, SKIN['dark'], SKIN['base'], SKIN['hi'], SKIN['ol'], rim=None)

    def shadow_under(self, c, p):
        pass

    # smear arc (sword trail baked into the keyframe)
    def draw_smear(self, c, pivot, sm, col, reach):
        """sm = (a0, a1, alpha[, r0 scale]) - wedge between two blade angles."""
        a0, a1, al = sm[0], sm[1], sm[2]
        r0 = sm[3] if len(sm) > 3 else 0.6
        n = max(4, int(abs(a1 - a0) / 5))
        span = a1 - a0
        # three nested wedges: faint wide -> bright narrow, each tapering toward the start angle
        for (inner_f, aa) in ((r0 - 0.1, 0.14), (r0 + (1 - r0) * 0.4, 0.26), (r0 + (1 - r0) * 0.72, 0.5)):
            outer = [vadd(pivot, vdir(a0 + span * i / n, reach * (0.6 + 0.4 * (i / n)))) for i in range(n + 1)]
            inner = [vadd(pivot, vdir(a0 + span * i / n, reach * (inner_f + (1 - inner_f) * 0.0 + 0.0) * (0.6 + 0.4 * (i / n)))) for i in range(n, -1, -1)]
            c.apoly(outer + inner, (col[0], col[1], col[2], int(al * aa)))
        edge = [vadd(pivot, vdir(a0 + span * i / n, reach * (0.6 + 0.4 * (i / n)))) for i in range(n // 3, n + 1)]
        c.pline(edge, mix(col, (255, 255, 255), 0.65), 0.7)

# ============================================================================
#  CECILIA  -  costume, hair, face and demonic katana renderer
# ============================================================================
def _cec_pal(name, dress, dress_d, dress_h, eye, edge, flame, aura, gem, black=(30, 24, 38), lace=(232, 214, 222), hair=None):
    hair = hair or ((26, 22, 36), (8, 6, 14), (104, 92, 140))
    return dict(
        name=name, dress=dress, dress_d=dress_d, dress_h=dress_h,
        black=black, black_d=shade(black, 0.45), black_h=tint(shade(black, 1.0), 62, 60, 78),
        lace=lace, lace_d=shade(lace, 0.72),
        hair=hair[0], hair_d=hair[1], hair_h=hair[2],
        eye=eye, eye_d=shade(eye, 0.55), glow=eye, edge=edge, flame=flame, aura=aura, gem=gem,
        trail=edge, boot=(24, 20, 30), boot_d=(6, 4, 12), boot_h=(120, 110, 150),
        hose=(26, 24, 34), hose_d=(6, 6, 12), hose_h=(88, 90, 134),
        blade_d=(20, 16, 28), blade=(52, 44, 68), blade_h=(158, 146, 184), metal=(176, 166, 188),
        wrap=shade(dress, 0.7),
    )


CECILIA_PALS = [
    _cec_pal('Crimson Asura', (168, 20, 46), (92, 8, 30), (236, 76, 96), (255, 48, 72), (255, 84, 108), (255, 112, 60), (255, 40, 70), (255, 40, 70)),
    _cec_pal('Azure Lament', (30, 76, 176), (14, 34, 104), (104, 170, 255), (70, 210, 255), (96, 224, 255), (110, 200, 255), (60, 160, 255), (90, 210, 255),
             hair=((20, 24, 44), (6, 8, 20), (96, 120, 190))),
    _cec_pal('Violet Sin', (122, 40, 172), (62, 16, 104), (206, 124, 255), (236, 90, 255), (232, 120, 255), (255, 120, 230), (190, 70, 255), (230, 100, 255),
             black=(34, 22, 44), hair=((34, 20, 48), (12, 6, 20), (140, 96, 190))),
    _cec_pal('Ivory Wrath', (226, 220, 204), (150, 140, 124), (255, 252, 238), (255, 196, 60), (255, 220, 120), (255, 200, 80), (255, 190, 70), (255, 200, 80),
             black=(46, 36, 30), lace=(255, 244, 226), hair=((236, 232, 224), (150, 144, 150), (255, 255, 255))),
]

CEC_HAIR_REST = [(-8, -3), (-13, 7), (-15, 19), (-14, 31)]


class CeciliaFig(Fig):
    # ------------------------------------------------------------------
    def paint(self, c, p, J):
        pal = self.pal
        z = p.get('z', '')
        # aura / ghost arms (behind everything)
        if p['aura'] > 0:
            c.soft(vlerp(p['hip'], p['ch'], 0.5), 52, pal['aura'], int(150 * min(1.0, p['aura'])))
        if p['fxa']:
            self.ghost_arms(c, p, J)
        if 'P' not in z:
            self.ponytail(c, p, J)
        self.hair_back(c, p, J)
        if 'a' in z:
            self.arm(c, p, J, 'A')
        self.arm(c, p, J, 'B', behind=('b' not in z))
        if 'f' not in z:
            self.leg(c, p, J, 'B')
        if 'F' not in z:
            self.leg(c, p, J, 'A')
        self.torso(c, p, J)
        self.skirt(c, p, J)
        if 'f' in z:
            self.leg(c, p, J, 'B')
        if 'F' in z:
            self.leg(c, p, J, 'A')
        if p['sheath'] is not False and (p['sheath'] is None or p['wa'] is not None):
            self.hip_saya(c, p, J)
        self.draw_neck(c, p, J)
        self.choker(c, p, J)
        self.head(c, p, J)
        if 'P' in z:
            self.ponytail(c, p, J)
        if 'a' not in z:
            self.arm(c, p, J, 'A')
        if p['sm']:
            self.draw_smear(c, J['haA'], p['sm'], pal['trail'], 56 * p['wl'])
        self.weapon(c, p, J)
        self.hands(c, p, J)

    # ------------------------------------------------------------------
    def ghost_arms(self, c, p, J):
        pal = self.pal
        base = vlerp(p['hip'], p['ch'], 0.8)
        for (hx, hy, ang) in p['fxa']:
            mid, end = ik2(base, (hx, hy), 18, 17, 1)
            col = (pal['aura'][0], pal['aura'][1], pal['aura'][2])
            c.strip([base, mid, end], (6.5, 4.0, 3.0), shade(col, 0.45), col, tint(col, 90), None, smooth=4)
            d = vdir(ang)
            g0 = vadd(end, vmul(d, 4))
            g1 = vadd(end, vmul(d, 52))
            c.strip([g0, g1], (3.0, 1.2), shade(col, 0.5), col, (255, 235, 235), None, smooth=0)
            c.soft(vlerp(g0, g1, 0.6), 22, col, 120)

    # ------------------------------------------------------------------
    def ponytail(self, c, p, J):
        pal = self.pal
        hd = p['hd']
        hw = p['hw']
        root = (hd[0] - 5.2 - hw * 1.6, hd[1] - 6.5)
        pts = p['hairA'] or CEC_HAIR_REST
        path = [root] + [(hd[0] + q[0], hd[1] + q[1]) for q in pts]
        # a sub-strand for volume
        path2 = [root] + [(hd[0] + q[0] * 1.0 + 3.0, hd[1] + q[1] * 1.0 - 1.5 + 0.1 * i) for i, q in enumerate(pts)]
        c.strip(path2, (6.5, 7.5, 6.0, 3.0, 0.8), pal['hair_d'], pal['hair'], None, SKIN['ol'], smooth=4)
        c.strip(path, (8.4, 9.6, 8.0, 4.6, 0.6), pal['hair_d'], pal['hair'], pal['hair_h'], SKIN['ol'], smooth=5)
        # strand lines
        cp = catmull(path, 5)
        n = len(cp)
        for off, al in ((-1.8, 120), (0.2, 170), (2.0, 100)):
            seg = [(cp[i][0] + off * (1 - i / n), cp[i][1] - 0.6) for i in range(1, n - 2)]
            if len(seg) > 2:
                c.sheen(seg, pal['hair_h'], 0.55, al)
        # tie ribbon and bow
        c.ball((root[0] - 0.5, root[1] + 0.2), 3.6, pal['dress_d'], pal['dress'], pal['dress_h'], SKIN['ol'])
        bw = 5.5
        rot = 215
        for s in (-1, 1):
            bp = [root, vadd(root, vrot((-bw, -3.5 * s), rot * 0)), vadd(root, (-bw * 1.5, -5.5 * s)), vadd(root, (-bw * 1.7, -1.0 * s))]
            c.poly(bp, pal['dress'], SKIN['ol'], 0.6)
        c.circle(root, 1.7, pal['dress_d'], SKIN['ol'], 0.4)

    def hair_back(self, c, p, J):
        pal = self.pal
        L = self.head_xf(p)
        hw = p['hw']
        pts = []
        for i in range(0, 15):
            t = math.pi * 0.85 + (math.pi * 1.3) * i / 14
            pts.append(L(math.cos(t) * 11.0 - hw * 1.2, math.sin(t) * 12.2 - 0.8))
        pts += [L(-10.5 - hw * 1.2, 7), L(-6, 8.5)]
        c.poly(pts, pal['hair_d'], SKIN['ol'])

    # ------------------------------------------------------------------
    def torso(self, c, p, J):
        pal = self.pal
        hip, ch = p['hip'], p['ch']
        r, sg = J['perp'], J['sg']
        spread = max(1.6, 11.0 * (1 - abs(p['tw']) ** 1.4 * 0.88))
        cs = clamp(spread / 11.0, 0.12, 1.0)
        sn = math.sqrt(max(0.0, 1 - cs * cs))

        def lv(t):
            return vlerp(hip, ch, t)

        def hwid(wf, ws):
            return math.hypot(wf * cs, ws * sn)

        near, far = -sg, sg
        levels = [(0.98, spread + 1.4, 0.0), (0.80, hwid(10.2, 8.2), 0.0), (0.66, hwid(9.4, 7.6), 2.6), (0.44, hwid(6.6, 5.6), 0.8), (0.22, hwid(7.8, 6.8), 0.0), (0.06, hwid(8.4, 7.4), 0.0)]
        left = [vadd(lv(t), vmul(r, near * w)) for t, w, b in levels]
        right = [vadd(lv(t), vadd(vmul(r, far * w), vmul(r, far * b * sn))) for t, w, b in levels]
        neck_l = vadd(ch, vmul(r, near * 3.4))
        neck_r = vadd(ch, vmul(r, far * 3.4))
        poly = [neck_l] + left + right[::-1] + [neck_r]
        c.poly_shaded(poly, pal['dress_d'], pal['dress'], pal['dress_h'], SKIN['ol'])
        # centre front line (shifted toward facing side)
        fo = sn * 5.2 * far

        def cf(t, extra=0.0):
            return vadd(lv(t), vmul(r, fo + extra))
        # corset (black) between waist levels
        t_top, t_bot = 0.52, 0.20
        cl = [vadd(lv(t), vmul(r, near * hwid(6.8 + (0.52 - t) * 8, 5.8))) for t in (t_top, 0.36, t_bot)]
        cr = [vadd(lv(t), vmul(r, far * hwid(6.8 + (0.52 - t) * 8, 5.8))) for t in (t_top, 0.36, t_bot)]
        c.poly_shaded(cl + cr[::-1], pal['black_d'], pal['black'], pal['black_h'], SKIN['ol'], 0.6)
        # lacing X
        steps = 5
        for i in range(steps):
            t1 = lerp(t_top, t_bot, i / steps)
            t2 = lerp(t_top, t_bot, (i + 1) / steps)
            c.line(cf(t1, -1.9), cf(t2, 1.9), pal['dress_h'], 0.6)
            c.line(cf(t1, 1.9), cf(t2, -1.9), pal['dress_h'], 0.6)
        c.line(cf(t_top), cf(t_bot), pal['dress_d'], 0.4)
        # bust shading + seam
        bc = vadd(lv(0.68), vmul(r, far * (2.0 + sn * 3.0)))
        c.pline([vadd(bc, vmul(r, -4.2)), vadd(bc, (0, 3.2)), vadd(bc, vmul(r, 4.2))], pal['dress_d'], 0.8)
        c.sheen([vadd(bc, vmul(r, -2.5)), vadd(bc, (0.3, -1.0)), vadd(bc, vmul(r, 1.6))], pal['dress_h'], 0.8, 150)
        # black lace frill across the chest (jabot)
        fr0 = vadd(lv(0.93), vmul(r, near * 7.2))
        fr1 = vadd(lv(0.93), vmul(r, far * 7.2))
        frill = []
        for i in range(0, 9):
            t = i / 8.0
            base_pt = vlerp(fr0, fr1, t)
            dip = 3.2 + (1.6 if i % 2 else 0.0)
            frill.append(vadd(base_pt, (0, dip)))
        c.poly([fr0, fr1] + frill[::-1], pal['black'], SKIN['ol'], 0.6)
        c.pline(frill, pal['lace'], 0.55)
        # big bow with gem
        bp = cf(0.82)
        for s in (-1, 1):
            wing = [bp, vadd(bp, vmul(r, s * 3.0)), vadd(bp, vadd(vmul(r, s * 6.4), (0, -2.0))), vadd(bp, vadd(vmul(r, s * 6.8), (0, 2.6))), vadd(bp, vadd(vmul(r, s * 3.0), (0, 2.0)))]
            c.poly(wing, pal['dress'], SKIN['ol'], 0.55)
        tl = [bp, vadd(bp, (-1.8, 6)), vadd(bp, (0.8, 9)), vadd(bp, (2.4, 5))]
        c.poly(tl, pal['dress_d'], SKIN['ol'], 0.5)
        c.ball(bp, 2.0, shade(pal['gem'], 0.5), pal['gem'], (255, 230, 230), SKIN['ol'])
        c.soft(bp, 6, pal['gem'], 80)
        # waist belt buckle
        c.ball(cf(0.14), 1.6, shade(pal['metal'], 0.6), pal['metal'], (255, 255, 255), SKIN['ol'])

    # ------------------------------------------------------------------
    def skirt(self, c, p, J):
        pal = self.pal
        hip = p['hip']
        sk = p['sk'] or SK_REST
        r, sg = J['perp'], J['sg']
        wl = vadd(hip, (-8.2, -8.5))
        wr = vadd(hip, (8.2, -8.5))
        top_l = vadd(vlerp(hip, p['ch'], 0.16), vmul(r, -9.0))
        top_r = vadd(vlerp(hip, p['ch'], 0.16), vmul(r, 9.0))
        hem = [vadd(hip, q) for q in sk]
        # petticoat (lace) peeks under the skirt
        pet = [vadd(hip, (q[0] * 1.1, q[1] + 3.0)) for q in sk]
        frill = [top_l] + pet + [top_r]
        c.poly_shaded(frill, shade(pal['lace_d'], 0.8), pal['lace_d'], pal['lace'], SKIN['ol'], 0.6)
        # scalloped lace edge on petticoat
        sc = catmull(pet, 5)
        for i in range(0, len(sc) - 1, 2):
            c.circle((sc[i][0], sc[i][1] + 1.0), 1.5, pal['lace'], SKIN['ol'], 0.3)
        # crimson underlayer
        under = [vadd(hip, (q[0] * 1.04, q[1] + 1.2)) for q in sk]
        c.poly_shaded([top_l] + under + [top_r], pal['dress_d'], shade(pal['dress'], 0.82), pal['dress'], SKIN['ol'], 0.6)
        # outer black skirt with crimson inner panels
        outer = [top_l] + hem + [top_r]
        c.poly_shaded(outer, pal['black_d'], pal['black'], pal['black_h'], SKIN['ol'])
        # fold lines
        n = len(hem)
        for i in range(1, n - 1):
            tp = vlerp(top_l, top_r, i / (n - 1))
            c.pline([tp, vlerp(tp, hem[i], 0.55), hem[i]], pal['black_d'], 0.6)
        mid = hem[n // 2]
        c.sheen([vlerp(top_l, top_r, 0.4), vlerp(vlerp(top_l, top_r, 0.4), hem[n // 2 - 1], 0.8)], pal['black_h'], 1.1, 120)
        # crimson ribbon trim along hem
        c.pline(catmull(hem, 4), pal['dress'], 1.5)
        c.pline(catmull([vadd(h, (0, -2.8)) for h in hem], 4), pal['dress_h'], 0.5)
        # waistband + big back bow
        c.poly([top_l, top_r, vadd(top_r, (0, 3.4)), vadd(top_l, (0, 3.4))], pal['dress'], SKIN['ol'], 0.5)
        bow = vadd(wl, (-3.0, -1.0))
        for s in (-1, 1):
            c.poly([bow, vadd(bow, (-7.0, -4.0 * s)), vadd(bow, (-11.0, -1.0 * s + 2)), vadd(bow, (-6.0, 3.2 * s))], pal['dress'], SKIN['ol'], 0.5)
        c.circle(bow, 2.0, pal['dress_d'], SKIN['ol'], 0.4)

    # ------------------------------------------------------------------
    def foot(self, c, an, ta, p=None):
        pal = self.pal
        f = vdir(ta)
        d = (-f[1], f[0])
        loc = [(-3.7, -2.0), (-4.3, 3.0), (-4.3, 5.0), (-1.0, 5.0), (-0.6, 3.7), (6.5, 3.8), (9.6, 5.0), (12.8, 4.4), (13.0, 2.8), (10.6, 1.4), (5.6, -0.4), (2.8, -2.0)]
        pts = [(an[0] + f[0] * x + d[0] * y, an[1] + f[1] * x + d[1] * y) for x, y in loc]
        c.poly_shaded(pts, pal['boot_d'], pal['boot'], pal['boot_h'], SKIN['ol'], 0.7)
        # toe-cap gloss and crimson strap
        t0 = (an[0] + f[0] * 8.0 + d[0] * 1.6, an[1] + f[1] * 8.0 + d[1] * 1.6)
        t1 = (an[0] + f[0] * 11.8 + d[0] * 3.3, an[1] + f[1] * 11.8 + d[1] * 3.3)
        c.sheen([t0, t1], (230, 230, 255), 0.7, 170)
        a0 = (an[0] + f[0] * 3.0 + d[0] * -1.6, an[1] + f[1] * 3.0 + d[1] * -1.6)
        a1 = (an[0] + f[0] * 4.0 + d[0] * 1.8, an[1] + f[1] * 4.0 + d[1] * 1.8)
        c.line(a0, a1, pal['dress'], 1.1)
        c.circle(vlerp(a0, a1, 0.5), 0.8, pal['metal'])

    def leg(self, c, p, J, side):
        pal = self.pal
        hp, kn, an = J['hp' + side], J['kn' + side], J['an' + side]
        ta = p['ta'] if side == 'A' else p['tb']
        c.tube(hp, kn, 9.4, 7.4, pal['hose_d'], pal['hose'], pal['hose_h'], SKIN['ol'])
        c.sheen_seg(hp, kn, 2.2, (210, 220, 255), 0.9, 190)
        bt = vlerp(kn, an, 0.40)
        c.tube(kn, bt, 7.2, 6.2, pal['hose_d'], pal['hose'], pal['hose_h'], SKIN['ol'])
        c.ball(kn, 3.9, pal['hose_d'], pal['hose'], pal['hose_h'], None)
        c.sheen([vadd(kn, (-1.0, -2.4)), vadd(kn, (1.4, -1.6))], (225, 230, 255), 0.8, 170)
        # boot shaft (glossy black leather)
        c.tube(bt, an, 6.6, 5.0, pal['boot_d'], pal['boot'], pal['boot_h'], SKIN['ol'])
        c.sheen_seg(bt, an, 1.7, (225, 230, 255), 0.8, 200, 0.1, 0.8)
        # boot cuff + lace frill
        n = c.lit_normal(bt, an)
        d = vnorm(vsub(an, bt))
        cuffA = vadd(bt, vmul(d, -1.6))
        c.tube(cuffA, vadd(bt, vmul(d, 1.4)), 7.8, 7.4, pal['dress_d'], pal['dress'], pal['dress_h'], SKIN['ol'], caps=False)
        pn = (-d[1], d[0])
        fr = []
        for i in range(-3, 4):
            fr.append(vadd(vadd(cuffA, vmul(pn, i * 2.0)), vmul(d, -1.2 - (1.1 if i % 2 else 0.0))))
        c.poly([vadd(cuffA, vmul(pn, -6.0)), vadd(cuffA, vmul(pn, 6.0))] + fr[::-1], pal['black'], SKIN['ol'], 0.45)
        c.pline(fr, pal['lace'], 0.45)
        # laces (crimson) and buckle
        for t in (0.3, 0.5, 0.7):
            pt = vlerp(bt, an, t)
            c.line(vadd(pt, vmul(pn, -2.4)), vadd(pt, vmul(pn, 2.4)), pal['dress'], 0.55)
        self.foot(c, an, ta, p)

    # ------------------------------------------------------------------
    def arm(self, c, p, J, side, behind=False):
        pal = self.pal
        sh, el, ha = J['sh' + side], J['el' + side], J['ha' + side]
        k = 0.8 if behind else 1.0
        sdark = shade(SKIN['dark'], k)
        # upper arm skin
        c.tube(sh, el, 5.8, 4.8, sdark, shade(SKIN['base'], k), SKIN['hi'] if not behind else None, SKIN['ol'])
        # ribbon band above elbow
        d = vnorm(vsub(el, sh))
        bp = vadd(el, vmul(d, -3.0))
        c.tube(vadd(bp, vmul(d, -0.8)), vadd(bp, vmul(d, 0.8)), 5.9, 5.9, pal['dress_d'], pal['dress'], None, SKIN['ol'], caps=False)
        # detached bell sleeve on forearm (black + lace cuff)
        fd = vnorm(vsub(ha, el))
        wr = vadd(ha, vmul(fd, -3.0))
        c.tube(vadd(el, vmul(fd, 1.0)), wr, 5.4, 6.8, shade(pal['black_d'], k), shade(pal['black'], k), pal['black_h'] if not behind else None, SKIN['ol'], caps=False)
        pn = (-fd[1], fd[0])
        cuff = []
        for i in range(-3, 4):
            cuff.append(vadd(vadd(wr, vmul(pn, i * 2.3)), vmul(fd, 1.8 + (1.4 if i % 2 else 0.0))))
        c.poly([vadd(wr, vmul(pn, -7.0)), vadd(wr, vmul(pn, 7.0))] + cuff[::-1], pal['black'], SKIN['ol'], 0.45)
        c.pline(cuff, pal['lace'], 0.5)
        c.line(vadd(wr, vmul(pn, -6.3)), vadd(wr, vmul(pn, 6.3)), pal['dress'], 1.0)
        # puffed shoulder sleeve
        c.ball(vadd(sh, vmul(d, 1.2)), 6.6, shade(pal['black_d'], k), shade(pal['black'], k), pal['black_h'] if not behind else None, SKIN['ol'])
        c.circle(vadd(sh, vmul(d, 5.2)), 0.1, pal['lace'])
        pn2 = (-d[1], d[0])
        ring = []
        for i in range(-3, 4):
            ring.append(vadd(vadd(vadd(sh, vmul(d, 5.4)), vmul(pn2, i * 2.0)), vmul(d, 0.9 if i % 2 else 0.0)))
        c.pline(ring, pal['lace'], 0.6)

    def hands(self, c, p, J):
        pal = self.pal
        glove = (pal['black_d'], pal['black'], pal['black_h'])
        self.draw_hand(c, J['haB'], glove=glove)
        self.draw_hand(c, J['haA'], glove=glove)

    # ------------------------------------------------------------------
    def choker(self, c, p, J):
        pal = self.pal
        ch = p['ch']
        hd = p['hd']
        a = (ch[0] - 3.2, ch[1] - 1.0)
        b = (ch[0] + 3.4 + p['hw'] * 0.8, ch[1] - 1.3)
        c.tube(a, b, 2.2, 2.2, pal['black_d'], pal['black'], pal['black_h'], SKIN['ol'])
        m = vlerp(a, b, 0.55)
        c.ball((m[0], m[1] + 1.2), 1.6, shade(pal['gem'], 0.5), pal['gem'], (255, 230, 230), SKIN['ol'])

    # ------------------------------------------------------------------
    def head(self, c, p, J):
        pal = self.pal
        self.draw_head_base(c, p)
        L = self.head_xf(p)
        hw, hu, ex = p['hw'], p['hu'], p['ex']
        fo = hw * 3.6
        ey = 2.4 + hu * 2.2
        sp = 3.9 * (1 - 0.22 * abs(hw))
        # far side is the side hw points toward
        near_x = fo - sp * (1 + 0.1 * max(hw, 0)) if hw >= 0 else fo - sp * (1 - 0.45 * abs(hw))
        far_x = fo + sp * (1 - 0.5 * max(hw, 0)) if hw >= 0 else fo + sp * (1 + 0.1 * abs(hw))
        wn = 3.4 * (1 + 0.08 * abs(hw))
        wf = 3.4 * (1 - 0.42 * max(hw, 0))
        if hw < 0:
            wn, wf = 3.4 * (1 - 0.42 * abs(hw)), 3.4 * (1 + 0.08 * abs(hw))
            near_x, far_x = fo - sp * (1 - 0.5 * abs(hw)), fo + sp * (1 + 0.1 * abs(hw))
        iris = (pal['eye'], pal['eye_d'])
        hei = 2.5
        if abs(hw) < 0.96:
            self.eye(c, L, near_x, ey, wn, hei, iris, ex, True, pal['glow'])
        if abs(hw) < 0.92:
            self.eye(c, L, far_x, ey, wf, hei, iris, ex, False, pal['glow'], flip=1.0)
        # eyeliner wings & brows
        self.brow(c, L, near_x, ey - 3.6, wn, ex, 1.0, pal['hair_d'])
        if abs(hw) < 0.92:
            self.brow(c, L, far_x, ey - 3.6, wf, ex, -1.0, pal['hair_d'])
        # nose, mouth, blush
        c.pline([L(fo * 1.15 + 0.2, ey + 2.8), L(fo * 1.2 + 0.7, ey + 4.1)], (200, 140, 140), 0.5)
        self.mouth(c, L, fo * 1.12, 7.7 + hu * 1.8, ex)
        c.soft(L(near_x - 0.4, ey + 3.3), 2.4, SKIN['blush'], 90)
        if abs(hw) < 0.9:
            c.soft(L(far_x + 0.4, ey + 3.3), 2.0, SKIN['blush'], 80)
        # jaw shadow cast on neck
        c.apoly([L(-5 + fo * 0.5, 9), L(5 + fo * 0.7, 9), L(4 + fo * 0.6, 12.6), L(-4 + fo * 0.5, 12.6)], (90, 40, 60, 90))
        self.hair_front(c, p, J, L)

    def hair_front(self, c, p, J, L):
        pal = self.pal
        hw = p['hw']
        fo = hw * 3.6
        cap = []
        for i in range(0, 13):
            t = math.pi + math.pi * i / 12
            cap.append(L(math.cos(t) * 9.7 + fo * 0.2, math.sin(t) * 10.6 - 0.4))
        sh = fo * 0.9
        bangs = [(9.4 + sh * 0.4, 3.4), (8.4 + sh, -0.6), (6.4 + sh, 1.4), (4.6 + sh, -1.6), (2.4 + sh, 0.6), (0.4 + sh, -2.2), (-1.8 + sh, 0.4),
                 (-4.0 + sh, -1.8), (-6.2 + sh * 0.7, 0.8), (-8.2 + sh * 0.5, -0.6), (-9.6 + sh * 0.3, 3.8)]
        poly = cap + [L(*b) for b in bangs]
        c.poly_shaded(poly, pal['hair_d'], pal['hair'], pal['hair_h'], SKIN['ol'], 0.7)
        # crown sheen arc
        arc = [L(-6.4 + fo * 0.3, -6.6), L(-2.0 + fo * 0.3, -9.0), L(3.4 + fo * 0.3, -8.6), L(7.0 + fo * 0.3, -5.0)]
        c.sheen(arc, (200, 190, 240) if pal['hair'][0] < 100 else (255, 255, 255), 1.1, 190)
        c.sheen([L(-7.6 + fo * 0.3, -3.6), L(-5.0 + fo * 0.3, -6.4)], pal['hair_h'], 0.7, 150)
        # side locks
        near_tip = p['hairB'][0] if p['hairB'] else (-9.2 - hw * 1.0, 19.0)
        far_tip = p['hairB'][1] if p['hairB'] and len(p['hairB']) > 1 else (9.0 - hw * 2.0, 17.0)
        c.strip([L(-9.0 + fo * 0.3, 1.5), L(-10.0 + (near_tip[0] + 9.2) * 0.3, 8.0), L(*near_tip)], (3.6, 3.4, 0.8), pal['hair_d'], pal['hair'], pal['hair_h'], SKIN['ol'], smooth=4)
        if hw < 0.7:
            c.strip([L(9.0 + fo * 0.3, 1.5), L(10.0 + (far_tip[0] - 9.0) * 0.3, 8.0), L(*far_tip)], (3.4, 3.0, 0.8), pal['hair_d'], pal['hair'], pal['hair_h'], SKIN['ol'], smooth=4)
        # headdress: black lace band with crimson bow, and tiny horns
        c.strip([L(-9.2 + fo * 0.3, -2.4), L(-4.0 + fo * 0.4, -7.4), L(2.0 + fo * 0.4, -8.2), L(8.6 + fo * 0.3, -3.6)], (2.8, 3.2, 3.2, 2.8), pal['black_d'], pal['black'], pal['black_h'], SKIN['ol'], smooth=4)
        c.pline([L(-9.2 + fo * 0.3, -1.0), L(-4.0 + fo * 0.4, -5.9), L(2.0 + fo * 0.4, -6.7), L(8.6 + fo * 0.3, -2.2)], pal['lace'], 0.5)
        bp = L(-7.6 + fo * 0.3, -6.2)
        for s in (-1, 1):
            c.poly([bp, vadd(bp, (-3.0 * s, -5.0)), vadd(bp, (-6.6 * s, -3.0)), vadd(bp, (-5.0 * s, 1.2))], pal['dress'], SKIN['ol'], 0.5)
        c.circle(bp, 1.5, pal['dress_d'], SKIN['ol'], 0.4)
        hb = L(2.0 + fo * 0.4, -9.2)
        c.poly([vadd(hb, (-1.8, 0.6)), vadd(hb, (-0.4, -6.6)), vadd(hb, (1.8, 0.4))], pal['dress_d'], SKIN['ol'], 0.5)
        c.sheen([vadd(hb, (-0.6, -0.5)), vadd(hb, (-0.2, -4.6))], pal['dress_h'], 0.5, 200)

    # ------------------------------------------------------------------
    def hip_saya(self, c, p, J):
        pal = self.pal
        ang = p['sheath'] if isinstance(p['sheath'], (int, float)) and p['wa'] is not None else 168.0
        base = vadd(J['hpA'], (2.0, -8.0))
        d = vdir(ang)
        n = (-d[1], d[0])
        tip = vadd(base, vmul(d, 38))
        c.strip([base, tip], (3.4, 2.8), pal['black_d'], pal['black'], pal['black_h'], SKIN['ol'], smooth=0)
        c.sheen_seg(base, tip, 0.8, (210, 200, 240), 0.5, 150)
        # crimson cord + koiguchi ring
        c.tube(vadd(base, vmul(d, 2.5)), vadd(base, vmul(d, 5.5)), 3.9, 3.9, pal['dress_d'], pal['dress'], None, SKIN['ol'], caps=False)
        c.tube(vadd(tip, vmul(d, -3.2)), tip, 3.0, 3.0, pal['metal'], (200, 190, 210), None, SKIN['ol'], caps=False)
        c.strip([vadd(base, vmul(d, 12)), vadd(vadd(base, vmul(d, 15)), (0, 8)), vadd(vadd(base, vmul(d, 12)), (-2, 15))], (1.2, 1.0, 0.6), pal['dress_d'], pal['dress'], None, None, smooth=3)

    # ------------------------------------------------------------------
    def weapon(self, c, p, J):
        pal = self.pal
        sheathed = isinstance(p['sheath'], (int, float)) and p['wa'] is None
        if p['wa'] is None and not sheathed:
            return
        ang = p['sheath'] if sheathed else p['wa']
        grip = J['haA']
        d = vdir(ang)
        n = (-d[1], d[0])
        L_ = 50.0 * p['wl']
        g = p['glow']
        # tsuka (grip wrap) and kashira
        pom = vadd(grip, vmul(d, -8.5))
        guard = vadd(grip, vmul(d, 5.4))
        c.tube(pom, guard, 3.6, 3.6, pal['wrap'] if False else shade(pal['dress_d'], 0.8), shade(pal['dress'], 0.75), pal['dress_h'], SKIN['ol'], caps=False)
        for i in range(5):
            q = vlerp(pom, guard, 0.12 + i * 0.19)
            c.line(vadd(q, vmul(n, -1.6)), vadd(q, vadd(vmul(n, 1.6), vmul(d, 1.2))), pal['black'], 0.5)
        c.poly([vadd(pom, vmul(d, -1.4)), vadd(pom, vadd(vmul(n, 2.2), (0, 0))), vadd(pom, vadd(vmul(d, 2.0), vmul(n, 0.2))), vadd(pom, vmul(n, -2.2))], pal['metal'], SKIN['ol'], 0.5)
        # tsuba: bat-wing demonic guard with spikes
        gp = guard
        wing = [vadd(gp, vadd(vmul(n, -7.8), vmul(d, -2.0))), vadd(gp, vadd(vmul(n, -5.0), vmul(d, 2.6))), vadd(gp, vmul(n, -2.6)),
                vadd(gp, vmul(d, 3.2)), vadd(gp, vmul(n, 2.6)), vadd(gp, vadd(vmul(n, 5.0), vmul(d, 2.6))), vadd(gp, vadd(vmul(n, 7.8), vmul(d, -2.0))),
                vadd(gp, vadd(vmul(n, 3.4), vmul(d, -3.2))), vadd(gp, vadd(vmul(n, -3.4), vmul(d, -3.2)))]
        c.poly_shaded(wing, pal['black_d'], pal['black'], pal['black_h'], SKIN['ol'], 0.55)
        c.ball(gp, 1.8, shade(pal['gem'], 0.5), pal['gem'], (255, 230, 230), SKIN['ol'])
        c.soft(gp, 8, pal['gem'], 100)
        if sheathed:
            tip = vadd(guard, vmul(d, L_ + 2))
            c.strip([vadd(guard, vmul(d, 1.5)), tip], (3.5, 2.6), pal['black_d'], pal['black'], pal['black_h'], SKIN['ol'], smooth=0)
            c.sheen_seg(guard, tip, 0.8, (215, 205, 245), 0.6, 160)
            c.tube(vadd(guard, vmul(d, 1.2)), vadd(guard, vmul(d, 5.0)), 4.0, 4.0, pal['dress_d'], pal['dress'], None, SKIN['ol'], caps=False)
            if g > 0:
                c.soft(vlerp(guard, tip, 0.5), 20, pal['edge'], int(70 * g))
            return
        # blade
        base0 = vadd(guard, vmul(d, 1.0))
        tip = vadd(guard, vmul(d, L_))
        sori = n
        # jagged spine teeth (demonic)
        spine = []
        edge = []
        N = 10
        for i in range(N + 1):
            t = i / N
            along = vlerp(base0, tip, t)
            curve = -math.sin(t * math.pi) * 1.1
            w = lerp(1.9, 1.35, t) * (1.0 if t < 0.9 else (1 - t) * 10)
            sp_pt = vadd(along, vmul(n, (w + curve) * -1.0))
            ed_pt = vadd(along, vmul(n, (w - curve) * 1.0))
            spine.append(sp_pt)
            edge.append(ed_pt)
        blade = spine + edge[::-1]
        if g > 0:
            c.soft(vlerp(base0, tip, 0.55), 30 * p['wl'], pal['edge'], int(110 * g))
        c.poly(blade, pal['blade'], SKIN['ol'], 0.7)
        # dark spine half, hamon edge half
        c.poly(spine + [vlerp(spine[i], edge[i], 0.5) for i in range(N, -1, -1)], pal['blade_d'])
        c.poly([vlerp(spine[i], edge[i], 0.62) for i in range(N + 1)] + edge[::-1], mix(pal['blade_h'], pal['edge'], 0.35))
        c.pline(edge, pal['edge'], 0.9)
        c.pline([vlerp(spine[i], edge[i], 0.35) for i in range(1, N)], pal['edge'], 0.5)       # glowing fuller
        c.sheen([vlerp(spine[i], edge[i], 0.55) for i in range(1, N - 1)], (255, 255, 255), 0.5, 190)
        # serrations along the spine
        for i in range(2, N - 1, 2):
            a0 = spine[i]
            c.poly([a0, vadd(vlerp(spine[i], spine[i + 1], 0.5), vmul(n, -2.2)), spine[i + 1]], pal['blade'], SKIN['ol'], 0.35)
        # demonic flame wisps near the tip
        if g > 0.25:
            for k_, off in enumerate((0.55, 0.72, 0.9)):
                q = vlerp(base0, tip, off)
                c.poly([vadd(q, vmul(n, 1.4)), vadd(q, vadd(vmul(d, -4.0 - k_ * 2), vmul(n, 3.8 * (1 if k_ % 2 else -1)))), vadd(q, vmul(n, -1.4))], pal['flame'], None)
            c.soft(tip, 7, (255, 255, 255), int(120 * g))

    # ------------------------------------------------------------------
    def draw_head_base(self, c, p):
        Fig.draw_head_base(self, c, p)


