# ============================================================================
#  KIRI  -  kitsune-masked twin-blade martial artist renderer
# ============================================================================
def _kiri_pal(name, dress, dress_d, red, hair, eye, trail, mask=(250, 246, 244), skin_gold=None, stock=(244, 244, 252), shoe=None):
    hair_d = shade(hair, 0.5)
    return dict(
        name=name, dress=dress, dress_d=dress_d, dress_h=tint(dress, 18, 18, 18),
        red=red, red_d=shade(red, 0.55), red_h=tint(red, 56, 50, 50),
        hair=hair, hair_d=hair_d, hair_h=tint(hair, 78, 66, 56),
        mask=mask, mask_d=shade(mask, 0.74), mask_h=(255, 255, 255),
        eye=eye, trail=trail, glow=trail, aura=trail,
        stock=stock, stock_d=mix(shade(stock, 0.78), (150, 160, 210), 0.35), stock_h=(252, 252, 255),
        shoe=shoe or dress, shoe_d=shade(shoe or dress, 0.72),
        steel=(206, 220, 236), steel_d=(120, 138, 164), steel_h=(255, 255, 255), gold=(236, 196, 96), gold_d=(150, 110, 40),
        wrap=shade(red, 0.8),
    )


KIRI_PALS = [
    _kiri_pal('Shrine Vixen', (250, 246, 246), (176, 172, 202), (204, 28, 46), (118, 70, 44), (255, 214, 96), (214, 236, 255)),
    _kiri_pal('Kitsune Night', (52, 48, 78), (20, 18, 40), (236, 186, 70), (216, 214, 232), (120, 230, 255), (255, 226, 130), mask=(44, 40, 62), stock=(54, 50, 74), shoe=(40, 36, 60)),
    _kiri_pal('Sakura Haze', (255, 220, 230), (206, 156, 176), (210, 44, 116), (74, 40, 60), (255, 140, 190), (255, 190, 220), stock=(255, 244, 248)),
    _kiri_pal('Azure Frost', (216, 238, 255), (140, 170, 214), (40, 92, 214), (46, 58, 104), (120, 240, 255), (150, 220, 255), stock=(236, 246, 255)),
]


def _ksk(preset):
    return [(x * 0.92, y * 0.74) for x, y in preset]


KSK_REST = _ksk(SK_REST)
KSK_FLARE = _ksk(SK_FLARE)
KSK_FLY = _ksk(SK_FLY)
KSK_BACK = _ksk(SK_BACK)
KSK_FWD = _ksk(SK_FWD)
KSK_CROUCH = _ksk(SK_CROUCH)
KSK_SPIN = _ksk(SK_SPIN)
KSK_DROP = _ksk(SK_DROP)

KT_REST = [(-6, 3), (-9, 14), (-8, 26), (-4, 36)]
KT_REST_F = [(-1, 2), (-4, 12), (-3, 24), (1, 34)]


class KiriFig(Fig):
    def paint(self, c, p, J):
        pal = self.pal
        z = p.get('z', '')
        if p['aura'] > 0:
            c.soft(vlerp(p['hip'], p['ch'], 0.5), 48, pal['aura'], int(120 * min(1.0, p['aura'])))
            self.foxfire(c, p)
        if p['fxa']:
            self.afterimages(c, p, J)
        self.twintail(c, p, 'far')
        self.hair_back(c, p, J)
        if 'a' in z:
            self.arm(c, p, J, 'A')
        if 'b' not in z:
            self.arm(c, p, J, 'B', behind=True)
            self.weapon(c, p, J, 'B', behind=True)
        if 'f' not in z:
            self.leg(c, p, J, 'B')
        if 'F' not in z:
            self.leg(c, p, J, 'A')
        self.torso(c, p, J)
        self.skirt(c, p, J)
        if 'f' in z:
            self.leg(c, p, J, 'B')
        if 'F' in z:
            self.leg(c, p, J, 'A')
        self.draw_neck(c, p, J)
        self.twintail(c, p, 'near')
        self.head(c, p, J)
        if 'b' in z:
            self.arm(c, p, J, 'B')
            self.weapon(c, p, J, 'B')
        if 'a' not in z:
            self.arm(c, p, J, 'A')
        if p['sm2']:
            self.draw_smear(c, J['haB'], p['sm2'], pal['trail'], 32 * p['wl'])
        if p['sm']:
            self.draw_smear(c, J['haA'], p['sm'], pal['trail'], 32 * p['wl'])
        self.weapon(c, p, J, 'A')
        self.draw_hand(c, J['haB'])
        self.draw_hand(c, J['haA'])

    # ------------------------------------------------------------------
    def foxfire(self, c, p):
        pal = self.pal
        a = p['aura']
        for i, (dx, dy) in enumerate(((-26, -96), (28, -112), (-18, -62))):
            q = (p['hip'][0] + dx, p['hip'][1] + dy + math.sin(i * 2.1) * 3)
            c.soft(q, 9, pal['trail'], int(140 * a))
            c.poly([vadd(q, (0, -7)), vadd(q, (3.2, 0)), vadd(q, (0, 4)), vadd(q, (-3.2, 0))], mix(pal['trail'], (255, 255, 255), 0.4))
            c.poly([vadd(q, (0, -4)), vadd(q, (1.6, 0)), vadd(q, (0, 2)), vadd(q, (-1.6, 0))], (255, 255, 255))

    def afterimages(self, c, p, J):
        """fxa = list of ghost blade tips (x, y, ang): phantom twin-blade echoes"""
        pal = self.pal
        for (hx, hy, ang) in p['fxa']:
            d = vdir(ang)
            a = (hx, hy)
            b = vadd(a, vmul(d, 30))
            col = pal['trail']
            c.strip([a, b], (2.4, 0.8), shade(col, 0.5), col, (255, 255, 255), None, smooth=0)
            c.soft(vlerp(a, b, 0.5), 14, col, 120)

    # ------------------------------------------------------------------
    def twintail(self, c, p, which):
        pal = self.pal
        hd, hw = p['hd'], p['hw']
        if which == 'near':
            root = (hd[0] - 8.2 - hw * 1.0, hd[1] - 2.5)
            pts = p['hairA'] or KT_REST
        else:
            root = (hd[0] + 4.8 - hw * 2.4, hd[1] - 4.0)
            pts = p['hairB'] or KT_REST_F
        path = [root] + [(hd[0] + q[0], hd[1] + q[1]) for q in pts]
        dk = 0.8 if which == 'far' else 1.0
        c.strip(path, (6.0, 7.0, 6.2, 3.6, 0.6), shade(pal['hair_d'], dk), shade(pal['hair'], dk), pal['hair_h'] if which == 'near' else None, SKIN['ol'], smooth=5)
        cp = catmull(path, 5)
        n = len(cp)
        for off, al in ((-1.4, 120), (0.9, 170)):
            seg = [(cp[i][0] + off * (1 - i / n), cp[i][1] - 0.5) for i in range(1, n - 3)]
            if len(seg) > 2:
                c.sheen(seg, pal['hair_h'], 0.5, al)
        # ribbon tie
        c.ball(root, 3.0, pal['red_d'], pal['red'], pal['red_h'], SKIN['ol'])
        for s in (-1, 1):
            c.poly([root, vadd(root, (-3.0, -4.6 * s)), vadd(root, (-7.0, -3.0 * s)), vadd(root, (-5.6, 1.4 * s))], pal['red'], SKIN['ol'], 0.5)
        c.circle(root, 1.3, pal['red_d'], SKIN['ol'], 0.3)

    def hair_back(self, c, p, J):
        pal = self.pal
        L = self.head_xf(p)
        hw = p['hw']
        pts = []
        for i in range(0, 15):
            t = math.pi * 0.85 + (math.pi * 1.3) * i / 14
            pts.append(L(math.cos(t) * 10.6 - hw * 1.2, math.sin(t) * 11.6 - 0.8))
        pts += [L(-9.5 - hw * 1.2, 5), L(-6, 6.5)]
        c.poly(pts, pal['hair_d'], SKIN['ol'])

    # ------------------------------------------------------------------
    def torso(self, c, p, J):
        pal = self.pal
        hip, ch = p['hip'], p['ch']
        r, sg = J['perp'], J['sg']
        spread = max(1.6, 11.0 * (1 - abs(p['tw']) ** 1.4 * 0.88))
        cs = clamp(spread / 11.0, 0.12, 1.0)
        sn = math.sqrt(max(0.0, 1 - cs * cs))

        def lv(t):
            return vlerp(hip, ch, t)

        def hwid(wf, ws):
            return math.hypot(wf * cs, ws * sn)
        near, far = -sg, sg
        levels = [(0.98, spread + 1.2, 0.0), (0.80, hwid(9.4, 7.6), 0.0), (0.66, hwid(8.6, 7.0), 2.2), (0.44, hwid(6.0, 5.2), 0.6), (0.22, hwid(7.4, 6.4), 0.0), (0.06, hwid(8.0, 7.0), 0.0)]
        left = [vadd(lv(t), vmul(r, near * w)) for t, w, b in levels]
        right = [vadd(lv(t), vadd(vmul(r, far * w), vmul(r, far * b * sn))) for t, w, b in levels]
        poly = [vadd(ch, vmul(r, near * 3.2))] + left + right[::-1] + [vadd(ch, vmul(r, far * 3.2))]
        c.poly_shaded(poly, pal['dress_d'], pal['dress'], pal['dress_h'], SKIN['ol'])
        fo = sn * 4.8 * far

        def cf(t, extra=0.0):
            return vadd(lv(t), vmul(r, fo + extra))
        # crossed kosode collar (red-edged lapels)
        l0 = vadd(ch, vmul(r, near * 3.4))
        l1 = cf(0.30, 2.0)
        r0 = vadd(ch, vmul(r, far * 3.4))
        r1 = cf(0.30, -2.0)
        c.strip([l0, vlerp(l0, l1, 0.5), l1], (2.8, 2.6, 2.2), pal['red_d'], pal['red'], pal['red_h'], SKIN['ol'], smooth=3, caps=False)
        c.strip([r0, vlerp(r0, r1, 0.5), r1], (2.8, 2.6, 2.2), pal['red_d'], pal['red'], pal['red_h'], SKIN['ol'], smooth=3, caps=False)
        # bust shading
        bc = vadd(lv(0.67), vmul(r, far * (1.8 + sn * 2.8)))
        c.pline([vadd(bc, vmul(r, -3.8)), vadd(bc, (0, 2.8)), vadd(bc, vmul(r, 3.8))], pal['dress_d'], 0.8)
        c.sheen([vadd(bc, vmul(r, -2.2)), vadd(bc, (0.2, -1.0)), vadd(bc, vmul(r, 1.4))], (255, 255, 255), 0.8, 190)
        # high red choker-collar and chest ribbon
        c.tube(vadd(ch, vmul(r, near * 3.8)), vadd(ch, vmul(r, far * 3.8)), 3.0, 3.0, pal['red_d'], pal['red'], pal['red_h'], SKIN['ol'])
        bp = cf(0.86)
        for s in (-1, 1):
            c.poly([bp, vadd(bp, vadd(vmul(r, s * 5.4), (0, -2.4))), vadd(bp, vadd(vmul(r, s * 6.2), (0, 2.8))), vadd(bp, (0, 1.6))], pal['red'], SKIN['ol'], 0.5)
        c.poly([bp, vadd(bp, (-1.6, 7)), vadd(bp, (0.4, 9.5)), vadd(bp, (2.0, 6))], pal['red_d'], SKIN['ol'], 0.5)
        c.ball(bp, 1.5, pal['gold_d'], pal['gold'], (255, 255, 230), SKIN['ol'])
        # obi sash (wide red belt)
        t0, t1 = 0.34, 0.12
        ol_ = [vadd(lv(t), vmul(r, near * hwid(6.6, 5.8))) for t in (t0, 0.22, t1)]
        or_ = [vadd(lv(t), vmul(r, far * hwid(6.6, 5.8))) for t in (t0, 0.22, t1)]
        c.poly_shaded(ol_ + or_[::-1], pal['red_d'], pal['red'], pal['red_h'], SKIN['ol'], 0.6)
        c.line(cf(t0, 0), cf(t1, 0), pal['red_d'], 0.5)
        c.ball(cf(0.23), 2.0, pal['gold_d'], pal['gold'], (255, 255, 230), SKIN['ol'])

    # ------------------------------------------------------------------
    def skirt(self, c, p, J):
        pal = self.pal
        hip = p['hip']
        sk = p['sk'] or KSK_REST
        r = J['perp']
        top_l = vadd(vlerp(hip, p['ch'], 0.15), vmul(r, -8.4))
        top_r = vadd(vlerp(hip, p['ch'], 0.15), vmul(r, 8.4))
        hem = [vadd(hip, q) for q in sk]
        # inner red petticoat
        pet = [vadd(hip, (q[0] * 1.05, q[1] + 2.4)) for q in sk]
        c.poly_shaded([top_l] + pet + [top_r], pal['red_d'], pal['red'], pal['red_h'], SKIN['ol'], 0.6)
        # white pleated outer skirt
        c.poly_shaded([top_l] + hem + [top_r], pal['dress_d'], pal['dress'], (255, 255, 255), SKIN['ol'])
        n = len(hem)
        for i in range(1, 2 * n - 2):
            t = i / (2 * n - 2)
            tp = vlerp(top_l, top_r, t)
            idx = min(n - 1, int(t * (n - 1)))
            hh = vlerp(hem[idx], hem[min(n - 1, idx + 1)], t * (n - 1) - idx)
            c.pline([tp, vlerp(tp, hh, 0.6), hh], pal['dress_d'], 0.45)
        c.sheen([vlerp(top_l, top_r, 0.38), vlerp(vlerp(top_l, top_r, 0.38), hem[n // 2 - 1], 0.8)], (255, 255, 255), 1.0, 200)
        # red hem band + gold stitch
        c.pline(catmull(hem, 4), pal['red'], 1.6)
        c.pline(catmull([vadd(h, (0, -2.4)) for h in hem], 4), pal['gold'], 0.35)
        # obi bow on the back
        bow = vadd(hip, (-8.4, -9.0))
        for s in (-1, 1):
            c.poly([bow, vadd(bow, (-6.0, -5.0 * s)), vadd(bow, (-11.0, -2.0 * s + 3)), vadd(bow, (-7.0, 4.4 * s))], pal['red'], SKIN['ol'], 0.5)
        c.poly([bow, vadd(bow, (-4.0, 9)), vadd(bow, (-7.4, 17)), vadd(bow, (-1.0, 11))], pal['red_d'], SKIN['ol'], 0.5)
        c.poly([bow, vadd(bow, (-8.0, 7)), vadd(bow, (-13.0, 12)), vadd(bow, (-6.0, 4))], pal['red'], SKIN['ol'], 0.5)
        c.circle(bow, 2.0, pal['red_d'], SKIN['ol'], 0.4)

    # ------------------------------------------------------------------
    def foot(self, c, an, ta):
        pal = self.pal
        f = vdir(ta)
        d = (-f[1], f[0])
        loc = [(-3.5, -2.0), (-4.0, 3.2), (-4.0, 4.6), (-1.2, 4.6), (-0.8, 3.8), (6.0, 4.0), (9.2, 5.0), (12.0, 4.4), (12.2, 3.0), (10.0, 1.6), (5.4, -0.4), (2.6, -2.0)]
        pts = [(an[0] + f[0] * x + d[0] * y, an[1] + f[1] * x + d[1] * y) for x, y in loc]
        c.poly_shaded(pts, pal['shoe_d'], pal['shoe'], (255, 255, 255), SKIN['ol'], 0.7)
        a0 = (an[0] + f[0] * 2.8 + d[0] * -1.8, an[1] + f[1] * 2.8 + d[1] * -1.8)
        a1 = (an[0] + f[0] * 4.4 + d[0] * 2.0, an[1] + f[1] * 4.4 + d[1] * 2.0)
        c.line(a0, a1, pal['red'], 1.2)
        c.circle(vlerp(a0, a1, 0.5), 0.8, pal['gold'])
        t0 = (an[0] + f[0] * 7.6 + d[0] * 1.4, an[1] + f[1] * 7.6 + d[1] * 1.4)
        t1 = (an[0] + f[0] * 10.8 + d[0] * 3.0, an[1] + f[1] * 10.8 + d[1] * 3.0)
        c.sheen([t0, t1], (255, 255, 255), 0.7, 200)

    def leg(self, c, p, J, side):
        pal = self.pal
        hp, kn, an = J['hp' + side], J['kn' + side], J['an' + side]
        ta = p['ta'] if side == 'A' else p['tb']
        c.tube(hp, kn, 8.2, 6.0, pal['stock_d'], pal['stock'], pal['stock_h'], SKIN['ol'])
        c.sheen_seg(hp, kn, 2.0, (255, 255, 255), 0.9, 210)
        c.tube(kn, an, 6.0, 4.0, pal['stock_d'], pal['stock'], pal['stock_h'], SKIN['ol'])
        c.sheen_seg(kn, an, 1.5, (255, 255, 255), 0.8, 200, 0.15, 0.85)
        c.circle(kn, 2.6, pal['stock'])
        c.sheen([vadd(kn, (-0.8, -1.6)), vadd(kn, (1.2, -1.0))], (255, 255, 255), 0.6, 120)
        # garter ribbon on upper thigh
        d = vnorm(vsub(kn, hp))
        gp = vlerp(hp, kn, 0.34)
        c.tube(vadd(gp, vmul(d, -1.0)), vadd(gp, vmul(d, 1.0)), 8.0, 7.8, pal['red_d'], pal['red'], pal['red_h'], SKIN['ol'], caps=False)
        c.ball(vadd(gp, vmul((-d[1], d[0]), 3.6)), 1.5, pal['gold_d'], pal['gold'], (255, 255, 230), SKIN['ol'])
        # ankle strap frill
        ad = vnorm(vsub(an, kn))
        ap = vadd(an, vmul(ad, -3.0))
        c.tube(vadd(ap, vmul(ad, -0.7)), vadd(ap, vmul(ad, 0.7)), 5.6, 5.4, pal['red_d'], pal['red'], None, SKIN['ol'], caps=False)
        self.foot(c, an, ta)

    # ------------------------------------------------------------------
    def arm(self, c, p, J, side, behind=False):
        pal = self.pal
        sh, el, ha = J['sh' + side], J['el' + side], J['ha' + side]
        k = 0.82 if behind else 1.0
        c.tube(sh, el, 5.2, 4.4, shade(SKIN['dark'], k), shade(SKIN['base'], k), SKIN['hi'] if not behind else None, SKIN['ol'])
        # red shoulder strap piece
        d = vnorm(vsub(el, sh))
        c.ball(vadd(sh, vmul(d, 1.0)), 5.2, shade(pal['dress_d'], k), shade(pal['dress'], k), None, SKIN['ol'])
        c.tube(vadd(sh, vmul(d, 3.8)), vadd(sh, vmul(d, 5.6)), 5.6, 5.6, shade(pal['red_d'], k), shade(pal['red'], k), None, SKIN['ol'], caps=False)
        # detached wide furisode sleeve with red lining
        fd = vnorm(vsub(ha, el))
        wr = vadd(ha, vmul(fd, -2.6))
        s0 = vadd(el, vmul(fd, -2.0))
        pn = (-fd[1], fd[0])
        drop = vnorm(vadd(vmul(fd, 0.5), (0, 1.0)))
        c.tube(s0, wr, 5.8, 8.0, shade(pal['dress_d'], k), shade(pal['dress'], k), (255, 255, 255) if not behind else None, SKIN['ol'], caps=False)
        flap = [vadd(wr, vmul(pn, -4.6)), vadd(wr, vmul(pn, 4.6)), vadd(vadd(wr, vmul(pn, 6.4)), vmul(drop, 9.0)), vadd(vadd(wr, vmul(pn, -1.0)), vmul(drop, 13.0)), vadd(vadd(wr, vmul(pn, -6.6)), vmul(drop, 8.0))]
        c.poly_shaded(flap, shade(pal['dress_d'], k), shade(pal['dress'], k), None, SKIN['ol'], 0.5)
        c.pline([flap[4], flap[3], flap[2]], pal['red'], 1.3)
        c.pline([flap[0], flap[1]], pal['red'], 1.1)
        # red cord at elbow
        c.tube(vadd(el, vmul(fd, 0.2)), vadd(el, vmul(fd, 1.6)), 5.4, 5.4, shade(pal['red_d'], k), shade(pal['red'], k), None, SKIN['ol'], caps=False)

    # ------------------------------------------------------------------
    def weapon(self, c, p, J, which, behind=False):
        pal = self.pal
        ang = p['wa'] if which == 'A' else p['wb']
        if ang is None:
            return
        hand = J['haA'] if which == 'A' else J['haB']
        d = vdir(ang)
        n = (-d[1], d[0])
        k = 0.82 if behind else 1.0
        L_ = 31.0 * p['wl']
        g = p['glow']
        pom = vadd(hand, vmul(d, -6.5))
        guard = vadd(hand, vmul(d, 3.6))
        c.tube(pom, guard, 3.0, 3.0, shade(pal['wrap'], 0.7 * k), shade(pal['red'], 0.85 * k), pal['red_h'], SKIN['ol'], caps=False)
        for i in range(3):
            q = vlerp(pom, guard, 0.2 + i * 0.28)
            c.line(vadd(q, vmul(n, -1.3)), vadd(q, vadd(vmul(n, 1.3), vmul(d, 0.9))), pal['gold'], 0.4)
        c.ball(pom, 1.7, pal['gold_d'], pal['gold'], (255, 255, 230), SKIN['ol'])
        c.ellipse(guard, 1.1, 3.6, pal['gold'], ang, SKIN['ol'], 0.45)
        c.ellipse(guard, 0.5, 2.4, pal['gold_d'], ang)
        base0 = vadd(guard, vmul(d, 0.8))
        tip = vadd(guard, vmul(d, L_))
        if g > 0:
            c.soft(vlerp(base0, tip, 0.55), 20 * p['wl'], pal['trail'], int(110 * g))
        N = 8
        spine, edge = [], []
        for i in range(N + 1):
            t = i / N
            along = vlerp(base0, tip, t)
            w = lerp(1.7, 1.2, t) * (1.0 if t < 0.88 else (1 - t) * 8.3)
            bow_ = -math.sin(t * math.pi) * 0.5
            spine.append(vadd(along, vmul(n, -(w + bow_))))
            edge.append(vadd(along, vmul(n, (w - bow_))))
        c.poly(spine + edge[::-1], pal['steel'], SKIN['ol'], 0.6)
        c.poly(spine + [vlerp(spine[i], edge[i], 0.5) for i in range(N, -1, -1)], pal['steel_d'])
        c.pline([vlerp(spine[i], edge[i], 0.66) for i in range(N + 1)], (255, 255, 255), 0.6)
        c.pline(edge, mix(pal['steel_h'], pal['trail'], 0.4), 0.5)
        c.sheen([vlerp(spine[i], edge[i], 0.42) for i in range(1, N - 1)], (255, 255, 255), 0.45, 220)
        if g > 0.4:
            c.soft(tip, 5, (255, 255, 255), int(130 * g))

    # ------------------------------------------------------------------
    def head(self, c, p, J):
        pal = self.pal
        self.draw_head_base(c, p)
        L = self.head_xf(p)
        hw, hu, ex = p['hw'], p['hu'], p['ex']
        fo = hw * 3.6
        ey = 1.6 + hu * 2.0
        sp = 3.9 * (1 - 0.22 * abs(hw))
        if hw >= 0:
            near_x = fo - sp * (1 + 0.1 * hw)
            far_x = fo + sp * (1 - 0.5 * hw)
            wn, wf = 3.2 * (1 + 0.08 * hw), 3.2 * (1 - 0.42 * hw)
        else:
            near_x = fo - sp * (1 - 0.5 * abs(hw))
            far_x = fo + sp * (1 + 0.1 * abs(hw))
            wn, wf = 3.2 * (1 - 0.42 * abs(hw)), 3.2 * (1 + 0.08 * abs(hw))
        # fox mask
        sh = fo * 0.9
        hl = self.head_xf(p)
        mk = [(-8.9 + sh * 0.3, 3.2), (-9.0 + sh * 0.3, -3.0), (-6.0 + sh * 0.5, -6.6), (0.0 + sh * 0.7, -7.6), (6.2 + sh * 0.6, -6.6), (9.0 + sh * 0.35, -3.0),
              (8.6 + sh * 0.35, 3.4), (5.0 + sh * 0.9, 5.4), (2.0 + sh * 1.1, 6.4), (0.4 + sh * 1.25, 8.0), (-1.4 + sh * 1.2, 6.4), (-5.0 + sh * 0.8, 5.4)]
        # fox ears (behind mask rim)
        for (b0, b1, tp, inner) in (((-7.4, -5.0), (-2.2, -7.8), (-9.0, -19.0), (-6.2, -8.6)), ((2.0, -7.8), (7.2, -4.8), (9.2, -18.0), (6.0, -8.4))):
            e = [L(b0[0] + sh * 0.5, b0[1]), L(tp[0] + sh * 0.5, tp[1]), L(b1[0] + sh * 0.5, b1[1])]
            c.poly(e, pal['mask'], SKIN['ol'], 0.7)
            c.poly([L(b0[0] * 0.78 + sh * 0.5 + 0.8, b0[1] - 1.0), L(tp[0] * 0.9 + sh * 0.5 + 0.2, tp[1] + 4.0), L(b1[0] * 0.78 + sh * 0.5, b1[1] - 1.0)], pal['red'])
            c.pline([L(tp[0] + sh * 0.5, tp[1]), L(tp[0] * 0.9 + sh * 0.5, tp[1] + 5.0)], pal['mask_d'], 0.5)
        c.poly_shaded([L(*q) for q in mk], pal['mask_d'], pal['mask'], pal['mask_h'], SKIN['ol'], 0.75)
        # red kitsune markings
        for s in (-1, 1):
            ex0 = (near_x if s < 0 else far_x)
            if s > 0 and abs(hw) > 0.93:
                continue
            c.pline([L(ex0 + s * 0.6, ey - 0.8), L(ex0 + s * 4.2, ey - 3.2), L(ex0 + s * 6.2, ey - 6.0)], pal['red'], 1.0)
            c.pline([L(ex0 + s * 0.8, ey + 1.6), L(ex0 + s * 4.6, ey + 2.2)], pal['red'], 0.6)
            c.pline([L(ex0 + s * 0.4, ey + 2.4), L(ex0 + s * 4.0, ey + 4.4)], pal['red'], 0.5)
        for dx in (-1.6, 0, 1.6):
            c.pline([L(sh * 0.7 + dx * 1.0, -7.0), L(sh * 0.7 + dx * 0.8, -3.2 - abs(dx) * 0.6)], pal['red'], 0.7)
        c.poly([L(0.0 + sh * 1.25 - 1.1, 6.4), L(0.4 + sh * 1.25, 8.2), L(1.4 + sh * 1.25, 6.2)], pal['red'])
        # eye slits with glint
        for (ex_, w_, far_) in ((near_x, wn, False), (far_x, wf, True)):
            if far_ and abs(hw) > 0.92:
                continue
            hh = {0: 1.0, 1: 0.6, 2: 1.5, 3: 0.2, 4: 0.8, 5: 0.15, 6: 0.7}.get(ex, 1.0)
            slit = [L(ex_ - w_ * 0.9, ey + 0.4), L(ex_ - w_ * 0.2, ey - hh), L(ex_ + w_ * 0.9, ey - 0.7 * hh - 0.2), L(ex_ + w_ * 0.4, ey + hh * 0.5)]
            c.poly(slit, (18, 10, 20))
            if hh > 0.4:
                c.soft(L(ex_ + 0.2, ey), 2.2, pal['eye'], 130)
                c.circle(L(ex_ + w_ * 0.1, ey - 0.1), min(0.9, hh * 0.7) + 0.2, pal['eye'])
        # mouth (below mask) + chin shade
        self.mouth(c, L, fo * 1.12 + 0.2, 9.5 + hu * 1.2, ex, lip=(200, 80, 98))
        c.soft(L(near_x - 0.2, ey + 4.8), 2.2, SKIN['blush'], 70)
        self.hair_front(c, p, J, L)
        # mask cord
        c.pline([L(-9.0 + sh * 0.3, 0.6), L(-10.6 + sh * 0.2, 2.2), L(-12.8, 5.0)], pal['red'], 0.8)

    def hair_front(self, c, p, J, L):
        pal = self.pal
        hw = p['hw']
        fo = hw * 3.6
        sh = fo * 0.9
        cap = []
        for i in range(0, 13):
            t = math.pi + math.pi * i / 12
            cap.append(L(math.cos(t) * 9.6 + fo * 0.2, math.sin(t) * 10.4 - 0.4))
        # side-swept bangs (hem leaves the mask forehead visible)
        bangs = [(9.4 + sh * 0.4, 2.0), (8.0 + sh, -3.4), (5.6 + sh, -5.0), (2.0 + sh, -6.4), (-1.6 + sh, -5.2), (-4.4 + sh, -6.0), (-7.2 + sh * 0.6, -3.2), (-9.4 + sh * 0.3, 2.6)]
        c.poly_shaded(cap + [L(*b) for b in bangs], pal['hair_d'], pal['hair'], pal['hair_h'], SKIN['ol'], 0.7)
        c.sheen([L(-6.0 + fo * 0.3, -6.8), L(-1.0 + fo * 0.3, -9.4), L(4.6 + fo * 0.3, -8.4)], (255, 236, 210), 1.0, 170)
        # long side locks framing the face
        nt = p['hairB'][0] if False else (-9.6 - hw * 1.0, 15.0)
        c.strip([L(-8.8 + fo * 0.3, -2.0), L(-10.0, 5.0), L(*nt)], (3.2, 3.0, 0.8), pal['hair_d'], pal['hair'], pal['hair_h'], SKIN['ol'], smooth=4)
        if hw < 0.7:
            c.strip([L(8.8 + fo * 0.3, -2.0), L(10.0 - hw * 2, 5.0), L(9.2 - hw * 2.0, 13.0)], (3.0, 2.8, 0.8), pal['hair_d'], pal['hair'], pal['hair_h'], SKIN['ol'], smooth=4)
        # ahoge tuft
        top = L(1.4 + fo * 0.4, -9.8)
        c.strip([top, vadd(top, (-1.0, -4.0)), vadd(top, (1.6, -7.0))], (2.2, 1.6, 0.4), pal['hair_d'], pal['hair'], None, SKIN['ol'], smooth=3)

