# ============================================================================
#  SPRITE BANK  -  renders authored keyframes to cached, cropped, shaded sprites
# ============================================================================
CHAR_DEFS = {
    'cecilia': dict(fig=CeciliaFig, pals=CECILIA_PALS, book=CEC),
    'kiri': dict(fig=KiriFig, pals=KIRI_PALS, book=KIRI),
}
_BANKS = {}


class SpriteBank:
    def __init__(self, char_id, pal_idx):
        d = CHAR_DEFS[char_id]
        self.char = char_id
        self.pal_idx = pal_idx % len(d['pals'])
        self.pal = d['pals'][self.pal_idx]
        self.fig = d['fig'](self.pal)
        self.book = d['book']
        self.cache = {}
        self.flash = {}
        self.ghost = {}

    @staticmethod
    def get_bank(char_id, pal_idx):
        key = (char_id, pal_idx)
        b = _BANKS.get(key)
        if b is None:
            b = _BANKS[key] = SpriteBank(char_id, pal_idx)
        return b

    def _render(self, name, flip):
        pose = self.book.get(name) or self.book['idle0']
        surf = self.fig.render(pose, flip)
        r = surf.get_bounding_rect()
        if r.w < 2 or r.h < 2:
            r = pygame.Rect(0, 0, 2, 2)
        sub = surf.subsurface(r)
        w, h = max(1, int(round(r.w / SS))), max(1, int(round(r.h / SS)))
        spr = pygame.transform.smoothscale(sub, (w, h)).convert_alpha()
        ox = (r.x - CANVAS_OX * K_RENDER) / SS
        oy = (r.y - CANVAS_OY * K_RENDER) / SS
        e = (spr, int(round(ox)), int(round(oy)))
        self.cache[(name, flip)] = e
        return e

    def get(self, name, flip=False):
        e = self.cache.get((name, flip))
        if e is None:
            e = self._render(name, flip)
        return e

    def get_flash(self, name, flip, amt=200):
        k = (name, flip)
        e = self.flash.get(k)
        if e is None:
            spr, ox, oy = self.get(name, flip)
            e = (tint_surface(spr, (255, 255, 255), amt / 255.0), ox, oy)
            self.flash[k] = e
        return e

    def get_ghost(self, name, flip, col):
        k = (name, flip, col)
        e = self.ghost.get(k)
        if e is None:
            spr, ox, oy = self.get(name, flip)
            g = silhouette(spr, col)
            e = (g, ox, oy)
            self.ghost[k] = e
        return e

    def preload_iter(self, names=None):
        names = names or list(self.book.keys())
        for i, n in enumerate(names):
            self.get(n, False)
            self.get(n, True)
            if i % 6 == 5 or i == len(names) - 1:
                yield (i + 1) / len(names)


# ============================================================================
#  STAGE  -  "The Drowned Nave": ruined romanesque cathedral in a cursed swamp
# ============================================================================
def _dead_tree(surf, x, y, ang, length, depth, width, col, rng):
    if depth <= 0 or length < 4:
        return
    x2 = x + math.cos(ang) * length
    y2 = y + math.sin(ang) * length
    pygame.draw.line(surf, col, (x, y), (x2, y2), max(1, int(width)))
    n = 2 if depth > 1 else 1
    for i in range(n):
        da = rng.uniform(0.25, 0.7) * (1 if i == 0 else -1) + rng.uniform(-0.15, 0.15)
        _dead_tree(surf, x2, y2, ang + da, length * rng.uniform(0.62, 0.8), depth - 1, width * 0.68, col, rng)
    if rng.random() < 0.4 and depth > 2:
        _dead_tree(surf, x2, y2, ang + rng.uniform(-0.5, 0.5), length * 0.5, depth - 2, width * 0.5, col, rng)


def _arch_poly(cx, base_y, half_w, rise, steps=14):
    pts = [(cx - half_w, base_y)]
    for i in range(steps + 1):
        t = math.pi - math.pi * i / steps
        pts.append((cx + math.cos(t) * half_w, base_y - math.sin(t) * rise))
    pts.append((cx + half_w, base_y))
    return pts


class Stage:
    def __init__(self):
        rng = random.Random(1313)
        self.t = 0.0
        self.flash = 0.0
        self.next_bolt = 240
        self.sky = self.make_sky(rng)
        self.far = self.make_far(rng)
        self.mid = self.make_mid(rng)
        self.main = self.make_main(rng)
        self.fogs = [self.make_fog(rng, 1100, 150, a) for a in (46, 38, 54)]
        self.reeds = [self.make_reed(rng) for _ in range(5)]
        self.branches = [self.make_branch(rng) for _ in range(3)]
        self.souls = [dict(x=rng.uniform(0, STAGE_W), y=rng.uniform(250, 470), p=rng.uniform(0, 6.3), s=rng.uniform(0.2, 0.6), r=rng.uniform(4, 9), z=rng.choice((0.6, 1.0, 1.0, 1.25))) for _ in range(26)]
        self.embers = [dict(x=rng.uniform(0, STAGE_W), y=rng.uniform(100, 500), v=rng.uniform(0.25, 0.9), p=rng.uniform(0, 6.3)) for _ in range(40)]
        self.rune_glow = radial_alpha(120, (255, 40, 70), 1.4, 120)

    # ------------------------------------------------------------ layers
    def make_sky(self, rng):
        s = vgrad_surface(W, H, [(0, (8, 4, 20)), (0.38, (36, 12, 44)), (0.62, (96, 26, 54)), (0.78, (146, 48, 60)), (1, (30, 12, 28))]).convert()
        for _ in range(110):
            x, y = rng.randrange(W), rng.randrange(0, 260)
            b = rng.randrange(90, 220)
            s.set_at((x, y), (b, b * 0.8, b))
        mx, my = 706, 148
        draw_glow(s, (mx, my), 300, (130, 20, 46), 2.0)
        draw_glow(s, (mx, my), 170, (190, 60, 70), 2.4)
        pygame.draw.circle(s, (232, 138, 126), (mx, my), 66)
        pygame.draw.circle(s, (246, 176, 156), (mx - 6, my - 6), 58)
        for (dx, dy, r, c) in ((-20, -14, 14, (214, 120, 112)), (18, 10, 20, (210, 116, 110)), (-8, 28, 10, (216, 124, 116)), (26, -26, 8, (214, 120, 114)), (-30, 12, 7, (218, 128, 120))):
            pygame.draw.circle(s, c, (mx + dx, my + dy), r)
            pygame.draw.circle(s, (240, 170, 150), (mx + dx - 2, my + dy - 2), max(1, r - 4))
        pygame.draw.circle(s, (120, 30, 44), (mx + 22, my + 22), 52, 14)   # shadowed limb
        # cloud streaks
        cl = pygame.Surface((W, H), pygame.SRCALPHA)
        for i in range(16):
            y = rng.randrange(40, 330)
            x = rng.randrange(-100, W)
            w_ = rng.randrange(180, 520)
            h_ = rng.randrange(8, 26)
            col = (28 + rng.randrange(30), 10, 36 + rng.randrange(20), rng.randrange(60, 150))
            pygame.draw.ellipse(cl, col, (x, y, w_, h_))
        s.blit(cl, (0, 0))
        return s

    def make_far(self, rng):
        w = int(W + (STAGE_W - W) * 0.16)
        s = pygame.Surface((w, H), pygame.SRCALPHA)
        # distant ridge
        pts = [(0, 470)]
        x = 0
        while x < w + 40:
            pts.append((x, 372 + rng.randrange(-26, 22) + 14 * math.sin(x / 90.0)))
            x += 38
        pts += [(w, 470)]
        pygame.draw.polygon(s, (36, 14, 42), pts)
        # spires of a ruined city
        for i in range(7):
            bx = int(w * (0.06 + i * 0.14) + rng.randrange(-20, 20))
            bh = rng.randrange(60, 150)
            bw = rng.randrange(18, 34)
            pygame.draw.rect(s, (30, 12, 38), (bx, 400 - bh, bw, bh + 40))
            pygame.draw.polygon(s, (30, 12, 38), [(bx - 3, 400 - bh), (bx + bw // 2, 400 - bh - rng.randrange(30, 70)), (bx + bw + 3, 400 - bh)])
            for k in range(3):
                pygame.draw.rect(s, (200, 60, 70, 120), (bx + 5, 410 - bh + k * 22, 3, 8))
        for i in range(10):
            _dead_tree(s, rng.randrange(0, w), 440, -math.pi / 2 + rng.uniform(-0.2, 0.2), rng.uniform(40, 80), 6, rng.uniform(4, 6), (24, 10, 32), rng)
        fog = pygame.Surface((w, 120), pygame.SRCALPHA)
        for y in range(120):
            pygame.draw.line(fog, (116, 40, 62, int(120 * (y / 120) ** 1.4)), (0, y), (w, y))
        s.blit(fog, (0, 380))
        return s

    def make_mid(self, rng):
        w = int(W + (STAGE_W - W) * 0.46)
        s = pygame.Surface((w, H), pygame.SRCALPHA)
        cx = int(w * 0.52)
        base = 470
        stone = (44, 38, 58)
        stone_d = (28, 22, 40)
        stone_l = (86, 70, 100)

        def block(rect, col=stone):
            pygame.draw.rect(s, col, rect)
            x0, y0, ww, hh = rect
            for yy in range(y0, y0 + hh, 11):
                off = (yy // 11 % 2) * 9
                pygame.draw.line(s, stone_d, (x0, yy), (x0 + ww, yy))
                for xx in range(x0 + off, x0 + ww, 18):
                    pygame.draw.line(s, stone_d, (xx, yy), (xx, min(yy + 11, y0 + hh)))
            pygame.draw.line(s, stone_l, (x0, y0), (x0, y0 + hh), 2)
        # side arcades (ruined)
        for side in (-1, 1):
            for i in range(4):
                ax = cx + side * (390 + i * 110)
                if i == 3 and side == 1:
                    continue
                top = 330 + (i * 14 if i > 1 else 0)
                block((ax - 18, top, 36, base - top))
                pygame.draw.rect(s, stone_l, (ax - 22, top - 6, 44, 8))
                pygame.draw.rect(s, stone_d, (ax - 24, base - 10, 48, 12))
                if i < 3:
                    nx = ax + side * 110
                    pts = _arch_poly((ax + nx) / 2, top, 55, 56 - i * 6)
                    pygame.draw.polygon(s, stone, pts)
                    inner = _arch_poly((ax + nx) / 2, top, 40, 42 - i * 6)
                    pygame.draw.polygon(s, (14, 8, 26), inner)
                    pygame.draw.lines(s, stone_l, False, pts[1:-1], 2)
        # towers
        block((cx - 400, 80, 140, base - 80))
        pygame.draw.polygon(s, stone_d, [(cx - 400, 80), (cx - 360, 40), (cx - 330, 66), (cx - 300, 36), (cx - 260, 80)])
        block((cx + 262, 150, 130, base - 150))
        pygame.draw.polygon(s, stone_d, [(cx + 262, 150), (cx + 290, 120), (cx + 316, 146), (cx + 352, 112), (cx + 392, 150)])
        # nave facade
        block((cx - 260, 170, 522, base - 170))
        jag = [(cx - 260, 170)]
        xx = cx - 260
        while xx < cx + 262:
            xx += rng.randrange(18, 40)
            jag.append((min(xx, cx + 262), 170 - rng.randrange(0, 42) * (1 if 80 < xx - (cx - 260) < 420 else 0.3)))
        jag += [(cx + 262, 190), (cx - 260, 190)]
        pygame.draw.polygon(s, stone, jag)
        pygame.draw.lines(s, stone_l, False, jag[:-2], 2)
        # gable cross-beam and corbel table
        for k in range(24):
            pygame.draw.rect(s, stone_d, (cx - 260 + k * 22, 214, 14, 8))
        # rose window
        rx, ry, rr = cx, 262, 68
        pygame.draw.circle(s, (74, 62, 90), (rx, ry), rr + 8)
        pygame.draw.circle(s, (20, 6, 22), (rx, ry), rr)
        draw_glow(s, (rx, ry), rr + 50, (120, 20, 40), 2.2)
        pygame.draw.circle(s, (140, 24, 44), (rx, ry), rr - 8)
        for k in range(12):
            a = k * math.pi / 6
            pygame.draw.line(s, (74, 62, 90), (rx, ry), (rx + math.cos(a) * (rr - 6), ry + math.sin(a) * (rr - 6)), 4)
            pygame.draw.circle(s, (74, 62, 90), (rx + math.cos(a + 0.26) * (rr - 20), ry + math.sin(a + 0.26) * (rr - 20)), 9, 3)
        pygame.draw.circle(s, (74, 62, 90), (rx, ry), 16)
        pygame.draw.circle(s, (255, 60, 80), (rx, ry), 9)
        for (a, r_) in ((0.5, 52), (2.4, 48), (4.2, 56)):
            pygame.draw.circle(s, (20, 12, 28), (rx + math.cos(a) * r_, ry + math.sin(a) * r_), 15)   # missing glass
        pygame.draw.circle(s, stone_l, (rx, ry), rr + 8, 3)
        # lancet windows
        for dx in (-200, -130, 130, 200):
            pts = _arch_poly(cx + dx, 400, 17, 24)
            pygame.draw.polygon(s, (12, 6, 22), pts)
            col = (40, 170, 120) if abs(dx) > 150 else (200, 50, 70)
            pygame.draw.polygon(s, col, _arch_poly(cx + dx, 394, 11, 17))
            draw_glow(s, (cx + dx, 380), 40, shade(col, 0.5), 2.0)
            pygame.draw.lines(s, stone_l, False, pts[1:-1], 2)
        # great portal with archivolts
        for k, (hw_, rise) in enumerate(((84, 86), (72, 74), (60, 62))):
            pygame.draw.polygon(s, [(80, 68, 96), (56, 46, 70), (14, 6, 22)][k], _arch_poly(cx, base, hw_, rise))
        draw_glow(s, (cx, base - 40), 70, (110, 20, 60), 2.0)
        for k in range(5):
            pygame.draw.line(s, (36, 18, 44), (cx - 50 + k * 25, base), (cx - 50 + k * 25, base - 90), 2)
        pygame.draw.lines(s, stone_l, False, _arch_poly(cx, base, 84, 86)[1:-1], 3)
        # fallen masonry & rubble
        for _ in range(60):
            rx_ = cx + rng.randrange(-480, 480)
            pygame.draw.polygon(s, rng.choice((stone, stone_d, (58, 50, 72))), [(rx_, base), (rx_ + rng.randrange(6, 18), base - rng.randrange(4, 14)), (rx_ + rng.randrange(18, 30), base)])
        # ivy / moss dripping
        for _ in range(26):
            vx = cx + rng.randrange(-400, 400)
            vy = rng.randrange(180, 260)
            pygame.draw.line(s, (20, 50, 40), (vx, vy), (vx + rng.randrange(-4, 4), vy + rng.randrange(30, 110)), 2)
        # moon-side rim light + base fog
        fog = pygame.Surface((w, 140), pygame.SRCALPHA)
        for y in range(140):
            pygame.draw.line(fog, (92, 34, 58, int(190 * (y / 140) ** 1.6)), (0, y), (w, y))
        s.blit(fog, (0, base - 110))
        return s

    def make_main(self, rng):
        s = pygame.Surface((STAGE_W, H), pygame.SRCALPHA)
        # swamp water band
        for y in range(380, H):
            t = (y - 380) / (H - 380)
            col = mix((22, 20, 44), (8, 14, 24), min(1, t * 1.4))
            pygame.draw.line(s, col, (0, y), (STAGE_W, y))
        # moon reflection column on water
        for i in range(30):
            y = 392 + i * 3
            hw_ = 36 - i * 0.7 + rng.uniform(-6, 6)
            pygame.draw.line(s, (170, 60, 76, 90 - i * 2), (1300 - hw_ * 1.4, y), (1300 + hw_ * 1.4, y), 1)
        # stone causeway / platform in perspective
        top = 436
        pts = [(-20, top + 8), (240, top - 2), (STAGE_W - 240, top - 2), (STAGE_W + 20, top + 8), (STAGE_W + 20, H), (-20, H)]
        pygame.draw.polygon(s, (56, 46, 64), pts)
        for y in range(top, H):
            t = (y - top) / (H - top)
            pygame.draw.line(s, mix((70, 58, 80), (36, 28, 46), t ** 0.8), (0, y), (STAGE_W, y))
        pygame.draw.line(s, (120, 100, 128), (0, top), (STAGE_W, top), 3)
        pygame.draw.line(s, (20, 12, 28), (0, top + 6), (STAGE_W, top + 6), 2)
        # flagstones - converge to vanishing point
        vx, vy = STAGE_W / 2, 150
        for k in range(-30, 31):
            x_far = vx + k * 44
            x_near = vx + k * 130
            pygame.draw.line(s, (30, 22, 40), (x_far, top), (x_near, H), 1)
        yy = top
        step = 8
        while yy < H:
            pygame.draw.line(s, (30, 22, 40), (0, yy), (STAGE_W, yy), 1)
            yy += step
            step *= 1.34
        # cracks and moss
        for _ in range(60):
            x = rng.randrange(0, STAGE_W)
            y = rng.randrange(top + 8, H)
            pts2 = [(x, y)]
            for j in range(rng.randrange(3, 6)):
                x += rng.randrange(-22, 22)
                y += rng.randrange(2, 12)
                pts2.append((x, y))
            pygame.draw.lines(s, (14, 8, 20), False, pts2, 1)
        for _ in range(80):
            x = rng.randrange(0, STAGE_W)
            y = rng.randrange(top + 6, H - 4)
            pygame.draw.ellipse(s, (30, 70, 56, 120), (x, y, rng.randrange(10, 36), rng.randrange(3, 7)))
        # summoning circle (perspective ellipse) with runes
        cx, cy = STAGE_W // 2, 500
        for (rx_, ry_, wd, col) in ((420, 56, 3, (170, 30, 54)), (396, 52, 1, (230, 70, 90)), (300, 40, 2, (170, 30, 54)), (180, 24, 1, (230, 70, 90))):
            pygame.draw.ellipse(s, col, (cx - rx_, cy - ry_, rx_ * 2, ry_ * 2), wd)
        for k in range(12):
            a = k * math.pi / 6
            px, py = cx + math.cos(a) * 350, cy + math.sin(a) * 47
            pygame.draw.circle(s, (230, 70, 90), (int(px), int(py)), 3)
            pygame.draw.line(s, (200, 50, 74), (px - 6, py - 2), (px + 6, py + 2), 1)
            pygame.draw.line(s, (200, 50, 74), (px - 3, py + 4), (px + 3, py - 4), 1)
        for k in range(5):
            a1 = -math.pi / 2 + k * 2 * math.pi / 5
            a2 = -math.pi / 2 + ((k + 2) % 5) * 2 * math.pi / 5
            pygame.draw.line(s, (200, 50, 74), (cx + math.cos(a1) * 296, cy + math.sin(a1) * 40), (cx + math.cos(a2) * 296, cy + math.sin(a2) * 40), 1)
        # props: broken columns, candles, bone piles, gravestones, chains, skull spikes
        def column(x, h, broken=True):
            pygame.draw.rect(s, (62, 52, 76), (x - 17, top - h, 34, h + 18))
            pygame.draw.rect(s, (88, 74, 100), (x - 17, top - h, 8, h + 18))
            pygame.draw.rect(s, (40, 30, 52), (x + 9, top - h, 8, h + 18))
            pygame.draw.rect(s, (76, 64, 90), (x - 24, top + 10, 48, 14))
            if broken:
                pygame.draw.polygon(s, (62, 52, 76), [(x - 17, top - h), (x - 6, top - h - 12), (x + 4, top - h - 4), (x + 17, top - h - 16), (x + 17, top - h)])
            else:
                pygame.draw.rect(s, (88, 74, 100), (x - 24, top - h - 12, 48, 14))
            for k in range(4):
                pygame.draw.line(s, (36, 26, 46), (x - 17, top - h + 20 + k * (h // 4)), (x + 17, top - h + 20 + k * (h // 4)), 1)
        for (x, h, b) in ((120, 190, True), (420, 150, True), (700, 230, False), (1330, 210, False), (1620, 160, True), (1890, 200, True)):
            column(x, h, b)
        for x in (250, 520, 1100, 1460, 1760):
            for k in range(rng.randrange(3, 6)):
                cxk = x + rng.randrange(-24, 24)
                cyk = top + 28 + rng.randrange(0, 12)
                hh = rng.randrange(8, 18)
                pygame.draw.rect(s, (220, 206, 190), (cxk, cyk - hh, 5, hh))
                pygame.draw.circle(s, (255, 190, 90), (cxk + 2, cyk - hh - 3), 3)
        for x in (330, 960, 1540, 1830):
            for k in range(12):
                bx = x + rng.randrange(-34, 34)
                by = H - 20 + rng.randrange(-10, 14) - (30 - abs(bx - x)) * 0.2
                pygame.draw.line(s, (206, 196, 176), (bx, by), (bx + rng.randrange(-10, 10), by + rng.randrange(-4, 4)), 2)
            pygame.draw.circle(s, (214, 204, 184), (x, H - 26), 8)
            pygame.draw.circle(s, (20, 10, 20), (x - 3, H - 27), 2)
            pygame.draw.circle(s, (20, 10, 20), (x + 3, H - 27), 2)
        for x in (60, 880, 1220, 1960):
            pygame.draw.rect(s, (30, 70, 52), (x, top - 6, 6, 14))
            pygame.draw.line(s, (200, 190, 170), (x + 3, top - 40), (x + 3, top - 6), 2)
            pygame.draw.circle(s, (214, 204, 184), (x + 3, top - 46), 7)
            pygame.draw.circle(s, (255, 60, 70), (x + 1, top - 47), 1)
            pygame.draw.circle(s, (255, 60, 70), (x + 5, top - 47), 1)
        # hanging chains
        for x in (220, 1040, 1700):
            for k in range(14):
                pygame.draw.ellipse(s, (120, 114, 130), (x + math.sin(k * 0.4) * 4, 180 + k * 14, 8, 14), 2)
        # dead trees at the stage edges
        _dead_tree(s, 40, top + 4, -math.pi / 2, 120, 7, 12, (18, 10, 24), rng)
        _dead_tree(s, STAGE_W - 40, top + 4, -math.pi / 2 - 0.1, 130, 7, 12, (18, 10, 24), rng)
        return s

    def make_fog(self, rng, w, h, a):
        s = pygame.Surface((w, h), pygame.SRCALPHA)
        for _ in range(26):
            r = rng.randrange(30, 80)
            blob = radial_alpha(r, (150, 70, 100), 1.6, a)
            s.blit(blob, (rng.randrange(-20, w - r), rng.randrange(0, max(1, h - 2 * r))))
        return s

    def make_reed(self, rng):
        s = pygame.Surface((90, 150), pygame.SRCALPHA)
        for _ in range(16):
            x = rng.randrange(10, 80)
            h = rng.randrange(60, 140)
            lean = rng.uniform(-14, 14)
            pygame.draw.line(s, (10, 16, 18), (x, 150), (x + lean, 150 - h), 2)
            if rng.random() < 0.5:
                pygame.draw.ellipse(s, (30, 14, 18), (x + lean - 2, 150 - h - 9, 5, 14))
        return s

    def make_branch(self, rng):
        s = pygame.Surface((420, 260), pygame.SRCALPHA)
        _dead_tree(s, 420, 0, math.pi * 0.62, 190, 6, 9, (8, 6, 14), rng)
        return s

    # ------------------------------------------------------------ drawing
    def update(self):
        self.t += 1
        if self.flash > 0:
            self.flash -= 1
        self.next_bolt -= 1
        if self.next_bolt <= 0:
            self.flash = 12
            self.next_bolt = random.randrange(420, 1200)

    def _blit_layer(self, scr, layer, camx, f):
        x = int(camx * f)
        w = layer.get_width()
        x = clamp(x, 0, w - W)
        scr.blit(layer, (0, 0), area=pygame.Rect(x, 0, W, H))

    def draw_back(self, scr, camx):
        t = self.t
        scr.blit(self.sky, (-int(camx * 0.02), 0), area=None) if False else scr.blit(self.sky, (0, 0))
        if self.flash > 0:
            k = int(60 * (self.flash / 12.0) * (0.6 + 0.4 * (self.flash % 2)))
            scr.fill((k, int(k * 0.5), int(k * 0.9)), special_flags=pygame.BLEND_RGB_ADD)
        self._blit_layer(scr, self.far, camx, 0.16)
        # slow mid fog
        fx = int(-(t * 0.25 + camx * 0.3) % 1100)
        for i, fg in enumerate(self.fogs[:1]):
            scr.blit(fg, (fx - 1100, 330))
            scr.blit(fg, (fx, 330))
            scr.blit(fg, (fx + 1100, 330))
        self._blit_layer(scr, self.mid, camx, 0.46)
        self._blit_layer(scr, self.main, camx, 1.0)
        # animated water glints
        for i in range(14):
            gx = int((i * 143 + t * (0.4 + (i % 3) * 0.2) - camx) % (W + 60)) - 30
            gy = 388 + (i * 37) % 44
            pygame.draw.line(scr, (150 + int(60 * math.sin(t * 0.05 + i)), 60, 90), (gx, gy), (gx + 14 + i % 5, gy), 1)
        # rune circle pulse
        cx = STAGE_W // 2 - camx
        if -500 < cx < W + 500:
            pulse = 0.55 + 0.45 * math.sin(t * 0.05)
            r = self.rune_glow
            scr.blit(r, (int(cx - r.get_width() // 2 * 1.0), 500 - r.get_height() // 2 + 4), special_flags=0) if False else None
            g = glow_tex(150, (int(120 * pulse), int(16 * pulse), int(34 * pulse)), 1.6)
            scr.blit(pygame.transform.scale(g, (700, 110)), (int(cx - 350), 450), special_flags=pygame.BLEND_RGB_ADD)
        # souls (additive)
        for s_ in self.souls:
            if s_['z'] > 1.0:
                continue
            self._soul(scr, s_, camx, t)

    def _soul(self, scr, s_, camx, t):
        x = (s_['x'] - camx * s_['z'] + math.sin(t * 0.01 * s_['s'] + s_['p']) * 30) % (W + 100) - 50
        y = s_['y'] + math.sin(t * 0.02 * s_['s'] + s_['p'] * 2) * 22
        r = s_['r'] * (0.8 + 0.2 * math.sin(t * 0.05 + s_['p']))
        draw_glow(scr, (int(x), int(y)), int(r * 3.2), (60, 220, 160) if int(s_['p'] * 3) % 2 else (230, 70, 120), 2.0, 0.55)
        pygame.draw.circle(scr, (220, 255, 240), (int(x), int(y)), 2)

    def draw_front(self, scr, camx):
        t = self.t
        for s_ in self.souls:
            if s_['z'] > 1.0:
                self._soul(scr, s_, camx, t)
        for e in self.embers:
            x = (e['x'] - camx * 1.1 + math.sin(t * 0.02 + e['p']) * 20) % (W + 40) - 20
            y = (e['y'] - t * e['v']) % (H + 40) - 20
            c = 120 + int(100 * math.sin(t * 0.1 + e['p']))
            scr.set_at((int(x), int(y)), (255, c // 2, 40))
            scr.set_at((int(x) + 1, int(y)), (200, c // 3, 30))
        # foreground reeds and branch (parallax >1)
        for i, rd in enumerate(self.reeds):
            x = int((i * 520 + 40) - camx * 1.35)
            if -100 < x < W + 100:
                sway = int(math.sin(t * 0.03 + i) * 3)
                scr.blit(rd, (x + sway, H - 150 + 10))
        for i, br in enumerate(self.branches):
            x = int(i * 800 + 200 - camx * 1.25)
            if -430 < x < W:
                scr.blit(br, (x, -10))
        fx = int((t * 0.6 + camx * 0.9) % 1100)
        for fg in (self.fogs[2],):
            scr.blit(fg, (-fx, 430))
            scr.blit(fg, (1100 - fx, 430))
        vig = getattr(self, '_vig', None)
        if vig is None:
            vig = pygame.Surface((W, H), pygame.SRCALPHA)
            for i in range(60):
                a = int(150 * (1 - i / 60.0) ** 2.2)
                pygame.draw.rect(vig, (0, 0, 0, a), (i, i, W - 2 * i, H - 2 * i), 1)
            self._vig = vig
        scr.blit(vig, (0, 0))

# ============================================================================
#  INPUT  -  keyboard / gamepad / AI share one controller interface
# ============================================================================
BUTTONS = ('L', 'H', 'K', 'S', 'D')
K = pygame


class Controller:
    """poll() -> (dx, dy, pressed:set, held:set).  dx:-1 left/+1 right, dy:-1 up/+1 down"""
    def __init__(self):
        self.prev = set()

    def raw(self):
        return 0, 0, set()

    def poll(self):
        dx, dy, held = self.raw()
        pressed = held - self.prev
        self.prev = set(held)
        return dx, dy, pressed, held


class KeyboardController(Controller):
    def __init__(self, keys):
        super().__init__()
        self.keys = keys

    def raw(self):
        ks = pygame.key.get_pressed()

        def down(names):
            return any(ks[k] for k in names)
        dx = (1 if down(self.keys['right']) else 0) - (1 if down(self.keys['left']) else 0)
        dy = (1 if down(self.keys['down']) else 0) - (1 if down(self.keys['up']) else 0)
        held = set(b for b in BUTTONS if down(self.keys[b]))
        return dx, dy, held


KEYMAP_P1 = dict(left=[K.K_a], right=[K.K_d], up=[K.K_w], down=[K.K_s], L=[K.K_j], H=[K.K_k], K=[K.K_u], S=[K.K_i], D=[K.K_l])
KEYMAP_P2 = dict(left=[K.K_LEFT], right=[K.K_RIGHT], up=[K.K_UP], down=[K.K_DOWN], L=[K.K_KP1, K.K_COMMA], H=[K.K_KP2, K.K_PERIOD],
                 K=[K.K_KP3, K.K_SLASH], S=[K.K_KP5, K.K_SEMICOLON], D=[K.K_KP6, K.K_QUOTE])


class PadController(Controller):
    def __init__(self, joy):
        super().__init__()
        self.joy = joy

    def raw(self):
        j = self.joy
        try:
            ax = j.get_axis(0)
            ay = j.get_axis(1)
            dx = 1 if ax > 0.5 else (-1 if ax < -0.5 else 0)
            dy = 1 if ay > 0.5 else (-1 if ay < -0.5 else 0)
            if j.get_numhats() > 0:
                hx, hy = j.get_hat(0)
                if hx:
                    dx = hx
                if hy:
                    dy = -hy
            m = {'L': 0, 'K': 1, 'H': 2, 'S': 3, 'D': 5}
            held = set()
            for b, i in m.items():
                if i < j.get_numbuttons() and j.get_button(i):
                    held.add(b)
            return dx, dy, held
        except Exception:
            return 0, 0, set()


class MenuInput:
    """Edge-detected menu navigation for both players / pads."""
    def __init__(self):
        self.prev = set()
        self.rep = {}

    def poll(self):
        ks = pygame.key.get_pressed()
        cur = set()
        mp = {'up': (K.K_UP, K.K_w), 'down': (K.K_DOWN, K.K_s), 'left': (K.K_LEFT, K.K_a), 'right': (K.K_RIGHT, K.K_d),
              'ok': (K.K_RETURN, K.K_SPACE, K.K_j, K.K_KP_ENTER), 'back': (K.K_ESCAPE, K.K_BACKSPACE, K.K_k),
              'alt': (K.K_TAB, K.K_u), 'pause': (K.K_ESCAPE, K.K_p)}
        for name, keys in mp.items():
            if any(ks[k] for k in keys):
                cur.add(name)
        for joy in JOYS:
            try:
                ax, ay = joy.get_axis(0), joy.get_axis(1)
                if ax > 0.6:
                    cur.add('right')
                if ax < -0.6:
                    cur.add('left')
                if ay > 0.6:
                    cur.add('down')
                if ay < -0.6:
                    cur.add('up')
                if joy.get_numhats():
                    hx, hy = joy.get_hat(0)
                    if hx > 0:
                        cur.add('right')
                    if hx < 0:
                        cur.add('left')
                    if hy > 0:
                        cur.add('up')
                    if hy < 0:
                        cur.add('down')
                if joy.get_button(0):
                    cur.add('ok')
                if joy.get_button(1):
                    cur.add('back')
                if joy.get_numbuttons() > 3 and joy.get_button(3):
                    cur.add('alt')
                if joy.get_numbuttons() > 7 and joy.get_button(7):
                    cur.add('pause')
            except Exception:
                pass
        ev = set()
        for n in cur:
            if n not in self.prev:
                ev.add(n)
                self.rep[n] = 18
            elif n in ('up', 'down', 'left', 'right'):
                self.rep[n] -= 1
                if self.rep[n] <= 0:
                    ev.add(n)
                    self.rep[n] = 5
        self.prev = cur
        return ev


JOYS = []


# ============================================================================
#  VFX  -  particles, rings, slash arcs, starbursts, ground decals
# ============================================================================
class Particle:
    __slots__ = ('x', 'y', 'vx', 'vy', 'life', 'max', 'size', 'col', 'kind', 'g', 'drag')

    def __init__(self, x, y, vx, vy, life, size, col, kind, g=0.0, drag=0.98):
        self.x, self.y, self.vx, self.vy = x, y, vx, vy
        self.life = self.max = life
        self.size, self.col, self.kind, self.g, self.drag = size, col, kind, g, drag


class FX:
    def __init__(self):
        self.parts = []
        self.rings = []
        self.arcs = []
        self.bursts = []
        self.decals = []
        self.texts = []
        self.beams = []

    def clear(self):
        self.__init__()

    # ---- emitters
    def spark(self, x, y, col, n=10, speed=7.0, life=16, size=2, dirx=0.0, spread=6.28):
        for _ in range(n):
            a = random.uniform(0, spread) if dirx == 0 else (math.atan2(0, dirx) + random.uniform(-spread / 2, spread / 2))
            s = random.uniform(0.3, 1.0) * speed
            self.parts.append(Particle(x, y, math.cos(a) * s, math.sin(a) * s - 0.5, random.randrange(life // 2, life), size, col, 'spark', 0.12, 0.93))

    def blood(self, x, y, dirx, n=14, power=1.0):
        if not CFG['gore']:
            return
        for _ in range(n):
            a = math.atan2(-random.uniform(0.2, 1.4), dirx * random.uniform(0.4, 1.0))
            s = random.uniform(2.0, 8.0) * power
            col = random.choice(((150, 8, 22), (190, 14, 30), (104, 4, 16), (220, 30, 44)))
            self.parts.append(Particle(x, y, math.cos(a) * s, math.sin(a) * s, random.randrange(24, 54), random.uniform(1.5, 3.8) * min(1.5, power), col, 'blood', 0.34, 0.985))
        for _ in range(3):
            self.parts.append(Particle(x, y, dirx * random.uniform(0.5, 2), -random.uniform(0.3, 1.5), 22, random.uniform(6, 12), (90, 6, 18), 'mist', 0.0, 0.95))

    def smoke(self, x, y, col=(60, 40, 70), n=4, size=8):
        for _ in range(n):
            self.parts.append(Particle(x + random.uniform(-6, 6), y, random.uniform(-0.6, 0.6), -random.uniform(0.2, 1.0), random.randrange(24, 44), random.uniform(size * 0.6, size), col, 'smoke', -0.01, 0.97))

    def ember(self, x, y, col, n=6, up=2.0, life=40):
        for _ in range(n):
            self.parts.append(Particle(x + random.uniform(-10, 10), y + random.uniform(-10, 10), random.uniform(-1, 1), -random.uniform(0.5, up), random.randrange(life // 2, life), random.uniform(1.5, 3), col, 'glow', -0.02, 0.97))

    def dust(self, x, y, n=5, dirx=0):
        for _ in range(n):
            self.parts.append(Particle(x, y, random.uniform(-1.5, 1.5) + dirx, -random.uniform(0.2, 1.0), random.randrange(14, 26), random.uniform(5, 9), (120, 100, 120), 'smoke', 0.0, 0.93))

    def ring(self, x, y, col, r0=6, r1=70, life=16, width=3):
        self.rings.append([x, y, col, r0, r1, life, life, width])

    def arc(self, x, y, ang, length, col, life=8, width=14, sweep=70):
        self.arcs.append([x, y, ang, length, col, life, life, width, sweep])

    def burst(self, x, y, col, life=10, size=60, rays=8):
        self.bursts.append([x, y, col, life, life, size, rays, random.uniform(0, 3)])

    def decal(self, x):
        if not CFG['gore']:
            return
        self.decals.append([x, random.uniform(14, 34), 220, random.choice(((110, 6, 20), (80, 4, 14), (140, 10, 26)))])
        if len(self.decals) > 36:
            self.decals.pop(0)

    def beam(self, x0, y0, x1, y1, col, life=10, width=16):
        self.beams.append([x0, y0, x1, y1, col, life, life, width])

    def text(self, s, x, y, col, size=22, life=40):
        self.texts.append([s, x, y, col, size, life, life])

    # ---- update / draw
    def update(self):
        for p in self.parts:
            p.x += p.vx
            p.y += p.vy
            p.vy += p.g
            p.vx *= p.drag
            p.vy *= p.drag if p.kind != 'blood' else 1.0
            p.life -= 1
            if p.kind == 'blood' and p.y > GROUND_Y + 8 and p.life > 0:
                if random.random() < 0.3:
                    self.decal(p.x) if len(self.decals) < 34 and random.random() < 0.08 else None
                p.life = 0
        self.parts = [p for p in self.parts if p.life > 0]
        for r in self.rings:
            r[5] -= 1
        self.rings = [r for r in self.rings if r[5] > 0]
        for a in self.arcs:
            a[5] -= 1
        self.arcs = [a for a in self.arcs if a[5] > 0]
        for b in self.bursts:
            b[3] -= 1
        self.bursts = [b for b in self.bursts if b[3] > 0]
        for b in self.beams:
            b[5] -= 1
        self.beams = [b for b in self.beams if b[5] > 0]
        for t in self.texts:
            t[2] -= 0.6
            t[5] -= 1
        self.texts = [t for t in self.texts if t[5] > 0]
        for d in self.decals:
            d[2] = max(0, d[2] - 0.02)

    def draw_ground(self, scr, camx):
        for d in self.decals:
            x = d[0] - camx
            if -50 < x < W + 50:
                pygame.draw.ellipse(scr, d[3], (x - d[1], GROUND_Y - 2, d[1] * 2, 7))

    def draw(self, scr, camx):
        for p in self.parts:
            x, y = p.x - camx, p.y
            if x < -20 or x > W + 20:
                continue
            k = p.life / p.max
            if p.kind == 'spark':
                pygame.draw.line(scr, p.col, (x, y), (x - p.vx * 1.8, y - p.vy * 1.8), max(1, int(p.size * k + 0.5)))
            elif p.kind == 'blood':
                pygame.draw.circle(scr, p.col, (int(x), int(y)), max(1, int(p.size * (0.5 + 0.5 * k))))
            elif p.kind == 'glow':
                draw_glow(scr, (int(x), int(y)), int(p.size * 4 * (0.4 + k)), p.col, 2.0, k)
            elif p.kind in ('smoke', 'mist'):
                r = int(p.size * (1.5 - k * 0.5))
                if r > 1:
                    b = soft_blob(r, p.col)
                    b.set_alpha(int(110 * k))
                    scr.blit(b, (int(x) - r, int(y) - r))
        for b in self.beams:
            k = b[5] / b[6]
            w = max(1, int(b[7] * k))
            pygame.draw.line(scr, b[4], (b[0] - camx, b[1]), (b[2] - camx, b[3]), w)
            pygame.draw.line(scr, (255, 255, 255), (b[0] - camx, b[1]), (b[2] - camx, b[3]), max(1, w // 3))
        for r in self.rings:
            k = 1 - r[5] / r[6]
            rad = int(lerp(r[3], r[4], ease_out(k)))
            w = max(1, int(r[7] * (1 - k)))
            pygame.draw.circle(scr, r[2], (int(r[0] - camx), int(r[1])), rad, w)
        for a in self.arcs:
            x, y, ang, ln, col, life, mx, wd, sw = a
            k = 1 - life / mx
            n = 8
            a0 = ang - sw * 0.5 + sw * k * 0.35
            outer, inner = [], []
            for i in range(n + 1):
                t = i / n
                aa = math.radians(a0 + sw * t)
                taper = math.sin(t * math.pi) * (1 - k) * wd
                R = ln * (0.7 + 0.3 * ease_out(k + 0.2))
                outer.append((x - camx + math.cos(aa) * R, y + math.sin(aa) * R))
                inner.append((x - camx + math.cos(aa) * (R - taper), y + math.sin(aa) * (R - taper)))
            pygame.draw.polygon(scr, col, outer + inner[::-1])
            pygame.draw.lines(scr, (255, 255, 255), False, outer, 2)
        for b in self.bursts:
            x, y, col, life, mx, size, rays, rot = b
            k = life / mx
            for i in range(rays):
                aa = rot + i * TAU / rays
                L = size * (1 - k * 0.3) * (0.6 if i % 2 else 1.0)
                w = 5 * k + 1
                p0 = (x - camx + math.cos(aa) * 4, y + math.sin(aa) * 4)
                p1 = (x - camx + math.cos(aa) * L, y + math.sin(aa) * L)
                p2 = (x - camx + math.cos(aa + 0.18) * 8, y + math.sin(aa + 0.18) * 8)
                pygame.draw.polygon(scr, col if i % 2 else (255, 255, 255), [p0, p1, p2])
            draw_glow(scr, (int(x - camx), int(y)), int(size * 0.9), col, 2.0, k)
        for t in self.texts:
            draw_text(scr, t[0], t[4], (t[1] - camx, t[2]), t[3], 'center', alpha=int(255 * min(1, t[5] / 15.0)))

# ============================================================================
#  COMBAT DATA  -  frame data, hitboxes, motions and character definitions
#  (all values in logical pixels / 60 Hz ticks, authored facing right)
# ============================================================================
MV_DEFAULT = dict(
    dmg=40, hs=16, bs=10, kb=3.0, kbb=2.0, lvl='m', prio=1, tag='n', launch=None, kd=False, meter=30, gdmg=10,
    spark='slash', snd=None, vox=None, chain=(), move=(), ev=(), inv=None, air=False, chip=0.08, grab=None,
    curse=0, det=0, stop=None, through=None, land_to=None, cost=0, req_tempo=0, noturn=False, crush=False,
    nocombo=False, afterimg=False, multi=False, clash=True, fx=None,
)


def A(prefix, ticks):
    return [('%s%d' % (prefix, i), t) for i, t in enumerate(ticks)]


def mk(name, anim, hits=(), **kw):
    d = dict(MV_DEFAULT)
    d.update(kw)
    d['name'] = name
    d['anim'] = anim
    d['hits'] = [tuple(h) for h in hits]
    d['tot'] = sum(t for _, t in anim)
    if d['stop'] is None:
        d['stop'] = 5 if d['prio'] <= 1 else (8 if d['prio'] == 2 else 11)
    if d['snd'] is None:
        d['snd'] = 'swing_l' if d['prio'] <= 1 else 'swing_h'
    return d


